  gap: 7px;
  color: var(--text-2);
  font: 540 13px/1.45 ui-monospace, SFMono-Regular, Menlo, monospace;
}

.asg-knowledge-files code i {
  color: var(--text-3);
}

.asg-skill-core {
  position: relative;
  z-index: 2;
  display: grid;
  justify-items: center;
  gap: 4px;
  color: var(--brand);
}

.asg-skill-core::before,
.asg-skill-core::after {
  content: "";
  position: absolute;
  top: 35px;
  width: 40px;
  height: 2px;
  background: color-mix(in srgb, var(--brand) 42%, var(--border));
}

.asg-skill-core::before { right: calc(100% + 4px); }
.asg-skill-core::after { left: calc(100% + 4px); }

.asg-skill-core i {
  font-size: 56px;
}

.asg-skill-core strong {
  font-size: 15px;
}

.asg-value-labels {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 32px;
  margin-top: 16px;
}

.asg-value-labels > span {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 2px 10px;
  align-items: center;
  padding: 8px 0;
}

.asg-value-labels b {
  grid-row: 1 / 3;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: var(--on-brand);
  background: var(--brand);
  font-size: 12px;
}

.asg-value-labels strong {
  font-size: 14px;
}

.asg-value-labels small {
  color: var(--text-3);
  font-size: 12px;
}

/* 创建 */
.asg-create-scene {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) 42px minmax(220px, .75fr);
  align-items: center;
  gap: 22px;
  padding: 28px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--bg);
}

.asg-created-skill {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 16px 0;
}

.asg-created-skill > i {
  color: var(--brand);
  font-size: 48px;
}

.asg-created-skill > span {
  display: grid;
  gap: 5px;
}

.asg-created-skill strong {
  margin-bottom: 3px;
  font: 720 14px/1.45 ui-monospace, SFMono-Regular, Menlo, monospace;
}

.asg-created-skill code {
  color: var(--text-3);
  font: 540 12px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace;
}

.asg-create-steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
  margin: 22px 0 0;
  padding: 0;
  list-style: none;
}

.asg-create-steps li {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  align-items: start;
  gap: 10px;
}

.asg-create-steps span {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: var(--brand);
  background: var(--brand-light);
  font-size: 12px;
  font-weight: 750;
}

.asg-create-steps p {
  margin: 4px 0 0;
  color: var(--text-2);
  font-size: 13px;
  line-height: 1.6;
}

/* 测试 */
.asg-test-task {
  display: grid;
  justify-items: center;
  gap: 5px;
  margin-bottom: 18px;
  text-align: center;
}

.asg-test-task small {
  color: var(--brand);
  font-size: 12px;
  font-weight: 740;
}

.asg-test-task strong {
  font-size: 16px;
}

.asg-test-lanes {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.asg-test-lanes article {
  display: grid;
  gap: 14px;
  padding: 22px;
  border: 1px solid var(--border);
  border-radius: 13px;
  background: var(--bg-soft);
}

.asg-test-lanes article:last-child {
  border-color: color-mix(in srgb, var(--brand) 28%, var(--border));
  background: color-mix(in srgb, var(--brand-light) 40%, var(--bg));
}

.asg-test-lanes header {
  display: flex;
  align-items: center;
  gap: 9px;
}

.asg-test-lanes header i {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  color: var(--text-2);
  background: var(--bg);
  font-size: 18px;
}

.asg-test-lanes article:last-child header i {
  color: var(--brand);
}

.asg-test-lanes header strong {
  font-size: 14px;
}

.asg-test-lanes article > p {
  min-height: 44px;
  margin: 0;
  color: var(--text-2);
  font-size: 13px;
  line-height: 1.65;
}

.asg-test-output {
  min-height: 78px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 84px;
  gap: 8px;
  padding: 13px;
  border: 1px solid var(--border);
  border-radius: 9px;
  background: var(--bg);
}

.asg-test-output i {
  height: 7px;
  border-radius: 4px;
  background: var(--border);
}

.asg-test-output i:nth-child(2) {
  width: 66%;
}

.asg-test-output span {
  grid-column: 1 / -1;
  color: var(--text-3);
  font-size: 12px;
}

.asg-test-output.is-ready {
  border-color: color-mix(in srgb, var(--brand) 30%, var(--border));
}

.asg-test-output.is-ready i {
  background: color-mix(in srgb, var(--brand) 30%, var(--border));
}

.asg-test-output.is-ready span {
  color: var(--brand);
}

.asg-test-metrics {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 20px;
  margin-top: 16px;
}

.asg-test-metrics span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--text-2);
  font-size: 13px;
}

.asg-test-metrics i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--brand);
}

/* 最佳实践 */
.asg-practice-stage {
  min-height: 270px;
  display: grid;
  place-items: center;
  padding: 30px;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 16px;
  background:
    linear-gradient(color-mix(in srgb, var(--text) 2.2%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--text) 2.2%, transparent) 1px, transparent 1px),
    var(--bg);
  background-size: 24px 24px;
}

.asg-practice-stage > * {
  width: min(680px, 100%);
}

.asg-skill-editor {
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 11px;
  background: var(--bg);
  box-shadow: 0 14px 34px color-mix(in srgb, var(--text) 5%, transparent);
}

.asg-skill-editor header {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 38px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-soft);
}

.asg-skill-editor header i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border);
}

.asg-skill-editor header b {
  margin-left: 5px;
  color: var(--text-3);
  font: 620 12px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
}

.asg-skill-editor code {
  display: block;
  padding: 8px 16px;
  color: var(--text-2);
  font: 540 13px/1.65 ui-monospace, SFMono-Regular, Menlo, monospace;
  overflow-wrap: anywhere;
}

.asg-skill-editor code:first-of-type {
  padding-top: 16px;
}

.asg-skill-editor code:last-of-type {
  padding-bottom: 16px;
}

.asg-skill-editor code.is-highlighted {
  color: var(--brand);
  background: var(--brand-light);
}

.asg-skill-editor em {
  color: var(--brand);
  font-style: normal;
}

.asg-script-evidence {
  display: grid;
  grid-template-columns: minmax(210px, .8fr) minmax(0, 1.2fr);
  gap: 20px;
  align-items: stretch;
}

.asg-script-evidence > div {
  display: grid;
  place-items: center;
  align-content: center;
  gap: 7px;
  padding: 20px;
  border: 1px solid var(--border);
  border-radius: 11px;
  background: var(--bg);
  text-align: center;
}

.asg-script-evidence > div i {
  color: var(--brand);
  font-size: 34px;
}

.asg-script-evidence > div strong {
  font: 700 13px/1.45 ui-monospace, SFMono-Regular, Menlo, monospace;
}

.asg-script-evidence > div span {
  color: var(--text-3);
  font-size: 12px;
}

.asg-script-evidence pre {
  min-height: 168px;
  margin: 0;
  padding: 20px;
  border-radius: 11px;
  color: #e5e7eb;
  background: #15181e;
  font: 540 13px/1.8 ui-monospace, SFMono-Regular, Menlo, monospace;
  white-space: pre-wrap;
}

.asg-concise-evidence {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(170px, .7fr);
  align-items: center;
  gap: 24px;
}

.asg-concise-evidence > p {
  display: grid;
  gap: 5px;
  margin: 0;
}

.asg-concise-evidence > p strong {
  font-size: 16px;
  line-height: 1.45;
}

.asg-concise-evidence > p span {
  color: var(--text-3);
  font-size: 13px;
}

.asg-result-note {
  margin: 14px 0 0;
  color: var(--text-2);
  font-size: 14px;
  line-height: 1.7;
}

.asg-result-note strong {
  color: var(--text);
}

@media (max-width: 820px) {
  .agent-skill-guide {
    gap: 70px;
    margin-top: 62px;
  }

  .asg-install-scene,
  .asg-create-scene,
  .asg-value-scene {
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
  }

  .asg-install-arrow,
  .asg-create-arrow {
    transform: rotate(90deg);
  }

  .asg-installed-folder,
  .asg-created-skill {
    justify-content: center;
  }

  .asg-skill-core::before,
  .asg-skill-core::after {
    display: none;
  }

  .asg-value-labels,
  .asg-use-example,
  .asg-test-lanes,
  .asg-script-evidence,
  .asg-concise-evidence {
    grid-template-columns: minmax(0, 1fr);
  }

  .asg-create-steps {
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }
}

@media (max-width: 560px) {
  .agent-skill-guide {
    gap: 58px;
    margin-top: 52px;
  }

  .asg-heading {
    margin-bottom: 18px;
  }

  .asg-heading h2 {
    font-size: 28px;
  }

  .asg-heading p {
    font-size: 14px;
  }

  .asg-controls {
    flex-wrap: nowrap;
    max-width: 100%;
    margin-right: 0;
    padding-right: 0;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .asg-controls::-webkit-scrollbar {
    display: none;
  }

  .asg-controls button {
    flex: 0 0 auto;
  }

  .asg-install-scene,
  .asg-create-scene,
  .asg-value-scene,
  .asg-practice-stage {
    padding: 18px;
  }

  .asg-chat-window pre {
    padding: 15px;
    font-size: 12px;
  }

  .asg-use-example {
    gap: 16px;
    padding: 20px 18px;
  }

  .asg-test-lanes article {
    padding: 18px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .agent-skill-guide *,
  .agent-skill-guide *::before,
  .agent-skill-guide *::after {
    scroll-behavior: auto !important;
    transition-duration: .01ms !important;
    animation: none !important;
  }
}

/* ===== pack: backend ===== */
/* domains/web/network.css */
/* network module：网络基础（domain / dns / url / api / http / json / https / cdn） */

/* ---- 共用等宽字体 ---- */
.dom-demo, .dom-anat, .dns-demo, .dns-anat, .url-demo, .url-anat,
.api-demo, .api-anat, .http-demo, .http-anat, .json-demo, .json-anat,
.https-demo, .https-anat, .cdn-demo, .cdn-anat {
  font-family: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace;
}

/* ---- Domain 域名 ---- */
.dom-demo { display: flex; flex-direction: column; gap: 8px; }
.dom-demo-search {
  display: flex; align-items: center; gap: 8px;
  background: var(--bg); border: 1px solid var(--border); border-radius: 8px;
  padding: 8px 12px; font-size: 12px; color: var(--text-2);
  box-shadow: 0 0 0 3px rgba(99,102,241,.08);
}
.dom-demo-row {
  display: flex; align-items: center; gap: 8px;
  background: var(--bg); border: 1px solid var(--border-light); border-radius: 8px;
  padding: 8px 12px; font-size: 12px; color: var(--text);
}
.dom-demo-row .dom-name { font-weight: 600; }
.dom-demo-row .dom-price { margin-left: auto; color: var(--text-2); }
.dom-demo-row .dom-state { font-size: 12px; padding: 1px 7px; border-radius: 99px; }
.dom-demo-row .dom-state.ok { color: var(--green); background: var(--green-light); }
.dom-demo-row .dom-state.taken { color: var(--text-3); background: var(--bg-hover); }
.dom-demo-buy {
  font-size: 12px; color: var(--brand); background: var(--brand-light);
  border-radius: 5px; padding: 3px 9px;
}
.dom-demo-row :is(.dom-name, .dom-state, .dom-price, .dom-demo-buy) {
  white-space: nowrap;
}
@media (max-width: 720px) {
  .detail-entry-url .sc-body-inner {
    overflow-wrap: anywhere;
  }
  .dom-demo-row {
    display: grid; grid-template-columns: minmax(0, 1fr) auto;
  }
  .dom-demo-row .dom-state { justify-self: end; }
  .dom-demo-row .dom-price {
    grid-column: 1; grid-row: 2; margin-left: 0;
  }
  .dom-demo-row .dom-demo-buy {
    grid-column: 2; grid-row: 2; justify-self: end;
  }
  .dom-demo-row:not(:has(.dom-demo-buy)) .dom-price {
    grid-column: 2; justify-self: end;
  }
}
.dom-anat { display: inline-flex; align-items: center; gap: 2px; font-size: 15px; font-weight: 600; }
.dom-anat .dom-seg { padding: 3px 8px; border-radius: 6px; background: var(--bg); border: 1px solid var(--border); }
.dom-anat .dom-seg.sub { color: var(--brand); }
.dom-anat .dom-seg.root { color: var(--text); border-color: var(--brand); }
.dom-anat .dom-seg.tld { color: var(--warning); }
.dom-anat .dom-dot { color: var(--text-3); }

/* ---- DNS 解析 ---- */
.dns-demo { display: flex; align-items: stretch; gap: 6px; }
.dns-node {
  flex: 1; display: flex; flex-direction: column; align-items: center; gap: 4px;
  background: var(--bg); border: 1px solid var(--border); border-radius: 8px;
  padding: 8px 6px; text-align: center;
}
.dns-node .dns-ico { font-size: 18px; line-height: 1; }
.dns-node .dns-name { font-size: 12px; font-weight: 600; color: var(--text); font-family: -apple-system, "PingFang SC", sans-serif; }
.dns-node .dns-sub { font-size: 12px; color: var(--text-3); line-height: 1.4; }
.dns-arrow { align-self: center; color: var(--text-3); font-size: 12px; flex: none; }
.dns-anat { display: flex; align-items: stretch; gap: 6px; }
.dns-anat .dns-node .ap { display: contents; }
.dns-anat .dns-a {
  align-self: center; font-size: 12px; color: var(--brand); background: var(--brand-light);
  border-radius: 5px; padding: 3px 8px; white-space: nowrap; flex: none;
}

/* ---- URL 网址 ---- */
.url-demo { display: flex; flex-direction: column; gap: 10px; }
.url-bar {
  display: flex; align-items: stretch; flex-wrap: wrap;
  background: var(--bg); border: 1px solid var(--border); border-radius: 8px;
  overflow: hidden; font-size: 12px;
}
.url-seg { padding: 7px 4px; color: var(--text); white-space: nowrap; }
.url-seg.proto { background: var(--green-light); color: var(--green); }
.url-seg.host { background: var(--brand-light); color: var(--brand); font-weight: 600; }
.url-seg.path { background: var(--warning-light); color: var(--warning); }
.url-seg.query { background: var(--code-keyword-light); color: var(--code-keyword); }
.url-seg.hash { background: var(--bg-hover); color: var(--text-2); }
.url-legend { display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 12px; color: var(--text-3); font-family: -apple-system, "PingFang SC", sans-serif; }
.url-legend i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 4px; }
.url-anat .url-bar { font-size: 13px; }
.url-anat .ap { white-space: nowrap; }

/* ---- API 接口 ---- */
.api-demo { display: flex; flex-direction: column; gap: 8px; }
.api-req, .api-resp {
  background: var(--bg); border: 1px solid var(--border); border-radius: 8px;
  padding: 8px 12px; font-size: 12px; line-height: 1.7; color: var(--text);
}
.api-tag {
  display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .5px;
  border-radius: 4px; padding: 1px 6px; margin-bottom: 4px;
}
.api-req .api-tag { color: var(--brand); background: var(--brand-light); }
.api-resp .api-tag { color: var(--green); background: var(--green-light); }
.api-method { font-weight: 700; color: var(--brand); }
.api-key-token { color: var(--warning); }
.api-status-ok { color: var(--green); font-weight: 700; }
.api-arrow { text-align: center; color: var(--text-3); font-size: 12px; line-height: 1; }
.api-anat .api-code { font-size: 12px; line-height: 2; }
.api-anat .api-line { display: block; }

/* ---- HTTP 请求 ---- */
.http-demo { display: flex; flex-direction: column; gap: 8px; }
.http-msg {
  background: var(--bg); border: 1px solid var(--border); border-radius: 8px;
  padding: 8px 12px; font-size: 12px; line-height: 1.8; color: var(--text-2);
}
.http-msg .http-title { font-size: 12px; font-weight: 700; color: var(--text-3); letter-spacing: .5px; }
.http-method-get { color: var(--green); font-weight: 700; }
.http-method-post { color: var(--brand); font-weight: 700; }
.http-url { color: var(--text); }
.http-head { color: var(--text-3); }
.http-body {
  display: block; margin-top: 4px; background: var(--bg-soft);
  border: 1px dashed var(--border); border-radius: 5px; padding: 4px 8px; color: var(--text);
}
.http-anat .http-msg { font-size: 12px; }
.http-anat .ap { white-space: nowrap; }

/* ---- JSON 数据 ---- */
.json-demo, .json-anat {
  background: #1d2129; border-radius: 8px; padding: 10px 14px;
  font-size: 12px; line-height: 1.8; color: #c9cdd4;
}
.json-demo pre, .json-anat pre { margin: 0; white-space: pre-wrap; }
.json-k { color: #7db3ff; }
.json-s { color: #a6d189; }
.json-n { color: #ffb86c; }
.json-b { color: #f38ba8; }
.json-p { color: var(--code-muted); }
.json-anat .ap { white-space: nowrap; }

/* ---- HTTPS 安全连接 ---- */
.https-demo { display: flex; flex-direction: column; gap: 10px; }
.https-bar {
  display: flex; align-items: center; gap: 8px;
  background: var(--bg); border: 1px solid var(--border); border-radius: 99px;
  padding: 7px 14px; font-size: 12px; color: var(--text);
}
.https-bar .https-lock { color: var(--green); font-size: 12px; }
.https-bar .https-warn {
  font-size: 12px; color: var(--red); background: var(--red-light);
  border-radius: 99px; padding: 2px 8px; flex: none;
}
.https-bar.ok { border-color: #b7eb8f; }
.https-bar.bad { border-color: #ffa39e; }
.https-cap { font-size: 12px; color: var(--text-3); text-align: center; font-family: -apple-system, "PingFang SC", sans-serif; }
.https-anat { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.https-anat .https-cert {
  display: flex; flex-direction: column; gap: 2px;
  background: var(--bg); border: 1px solid var(--border); border-radius: 8px;
  padding: 6px 10px; font-size: 12px; color: var(--text-2); line-height: 1.5;
}
.https-anat .https-cert b { font-size: 12px; color: var(--text); font-family: -apple-system, "PingFang SC", sans-serif; }
.https-anat .https-tunnel {
  flex: 1; min-width: 60px; height: 8px; border-radius: 4px;
  background: repeating-linear-gradient(90deg, var(--green-light) 0 10px, #d3f2c2 10px 20px);
  border: 1px solid #b7eb8f; position: relative;
}

/* ---- CDN 加速 ---- */
.cdn-demo { display: flex; align-items: stretch; gap: 6px; }
.cdn-origin {
  flex: 1.1; display: flex; flex-direction: column; align-items: center; gap: 4px;
  background: var(--bg); border: 1px solid var(--brand); border-radius: 8px; padding: 8px 6px;
}
.cdn-edges { flex: 1.6; display: flex; flex-direction: column; gap: 5px; }
.cdn-edge {
  display: flex; align-items: center; gap: 6px;
  background: var(--bg); border: 1px solid var(--border-light); border-radius: 7px;
  padding: 4px 10px; font-size: 12px; color: var(--text-2);
  font-family: -apple-system, "PingFang SC", sans-serif;
}
.cdn-edge .cdn-ms { margin-left: auto; color: var(--green); font-family: ui-monospace, Menlo, monospace; }
