.db-grid { display: grid; grid-template-columns: 24px 1fr 1fr; }
.db-th { padding: 3px 9px; font-weight: 600; color: var(--text); background: var(--bg-soft); border-bottom: 1px solid var(--border-light); font-size:12px; }
