.stack-back-pipeline > em { color: var(--text-3); font-size: 11px; font-style: normal; }
.stack-response { flex-direction: row-reverse; }
.stack-response > i { margin: 0 auto 0 0; }

/* 详情页不是卡片缩略图：同步放大内容密度，而不只是拉宽外框。 */
.dh-demo .stack-window { border-radius: 12px; }
.dh-demo .stack-window-bar { height: 30px; gap: 6px; padding: 0 11px; }
.dh-demo .stack-window-bar i { width: 7px; height: 7px; }
.dh-demo .stack-window-bar span { margin-left: 7px; font-size: 11px; }
.dh-demo .stack-front-nav { padding: 11px 16px; }
.dh-demo .stack-front-nav b { font-size: 12px; letter-spacing: 1px; }
.dh-demo .stack-front-nav span { font-size: 11px; }
.dh-demo .stack-front-page {
  grid-template-columns: minmax(0, 1.25fr) minmax(120px, .75fr);
  gap: 22px; padding: 18px;
}
.dh-demo .stack-front-page > span { gap: 7px; }
.dh-demo .stack-front-page small { font-size: 12px; }
.dh-demo .stack-front-page strong { font-size: 19px; }
.dh-demo .stack-front-page em { font-size: 11px; }
.dh-demo .stack-front-page > span > b { padding: 7px 11px; border-radius: 7px; font-size: 11px; }
.dh-demo .stack-front-page > i { gap: 8px; padding: 14px; border-radius: 10px; }
.dh-demo .stack-front-page > i::before { font-size: 11px; }
.dh-demo .stack-front-page u { height: 7px; }
.dh-demo .stack-layer-row { gap: 8px; }
.dh-demo .stack-layer-row span { gap: 6px; padding: 9px 7px; border-radius: 8px; font-size: 11px; }
.dh-demo .stack-layer-row b { font-size: 11px; }

.dh-demo .stack-map-back { gap: 14px; padding: 18px; border-radius: 12px; }
.dh-demo .stack-request,
.dh-demo .stack-response { gap: 10px; padding: 11px 14px; border-radius: 9px; }
.dh-demo .stack-request > span { font-size: 11px; }
.dh-demo .stack-request > b,
.dh-demo .stack-response > b { padding: 3px 7px; border-radius: 5px; font-size: 11px; }
.dh-demo .stack-request code,
.dh-demo .stack-response code { font-size: 11px; }
.dh-demo .stack-request > i,
.dh-demo .stack-response > i { font-size: 11px; }
.dh-demo .stack-back-pipeline { gap: 9px; }
.dh-demo .stack-back-pipeline > span {
  min-height: 94px; gap: 5px; padding: 12px; border-radius: 9px;
}
.dh-demo .stack-back-pipeline > span > i { width: 22px; height: 22px; font-size: 11px; }
.dh-demo .stack-back-pipeline b { font-size: 13px; }
.dh-demo .stack-back-pipeline small { font-size: 12px; line-height: 1.45; }
.dh-demo .stack-back-pipeline > em { font-size: 12px; }

.frontend-anat {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px;
  width: min(100%, 530px);
}
.frontend-anat-part {
  display: flex; min-width: 0; flex-direction: column; gap: 4px; padding: 10px;
  border: 1px solid var(--border-light); border-radius: 8px; background: var(--bg);
}
.frontend-anat-part b { color: var(--text); font-size: 11px; }
.frontend-anat-part small { color: var(--text-3); font-size: 11px; line-height: 1.4; }
.frontend-anat-part.structure { border-top: 2px solid #e07a5f; }
.frontend-anat-part.style { border-top: 2px solid var(--brand); }
.frontend-anat-part.behavior { border-top: 2px solid #4d9b73; }
.frontend-anat-screen {
  grid-column: 1 / -1; display: flex; min-height: 66px; flex-direction: column;
  align-items: center; justify-content: center; gap: 4px; overflow: hidden;
  border: 1px solid var(--border); border-radius: 9px; background: var(--bg);
}
.frontend-anat-screen::before {
  content: ""; align-self: stretch; height: 13px; border-bottom: 1px solid var(--border-light);
  background: radial-gradient(circle at 9px 6px, var(--border) 0 2px, transparent 2.5px);
}
.frontend-anat-screen small { color: var(--brand); font-size: 11px; }
.frontend-anat-screen b { color: var(--text); font-size: 12px; }
.frontend-anat-screen i { width: 64px; height: 5px; border-radius: 99px; background: var(--brand); }
/* 基础概念的 use / don't 配图：用可读数据和状态解释文案。 */
.foundation-scene {
  display: flex; width: 100%; min-width: 0; flex-direction: column; gap: 7px;
}
.foundation-scene-head {
  color: var(--text-3); font-size: 10px; font-weight: 700; letter-spacing: .5px;
}
.foundation-note { color: var(--text-3); font-size: 11px; line-height: 1.45; }
.foundation-flow {
  display: flex; min-width: 0; align-items: center; justify-content: center; gap: 5px; flex-wrap: wrap;
}
.foundation-arrow { color: var(--text-3); font-size: 11px; }
.foundation-step {
  display: inline-flex; align-items: center; min-height: 24px; padding: 3px 8px;
  border: 1px solid var(--border); border-radius: 6px; background: var(--bg);
  color: var(--text-2); font-size: 11px; font-weight: 600; white-space: nowrap;
}
.foundation-step.blue, .foundation-box.blue {
  border-color: var(--border); background: var(--bg); color: var(--brand);
}
.foundation-step.green, .foundation-box.green {
  border-color: var(--border); background: var(--bg); color: var(--green);
}
.foundation-step.orange, .foundation-box.orange {
  border-color: var(--border); background: var(--bg); color: var(--warning);
}
.foundation-step.red, .foundation-box.red {
  border-color: var(--border); background: var(--bg); color: var(--red);
}
.foundation-boxes {
  display: grid; width: 100%; grid-template-columns: repeat(auto-fit, minmax(92px, 1fr)); gap: 6px;
}
.foundation-box {
  display: flex; min-width: 0; flex-direction: column; gap: 3px; padding: 7px 8px;
  border: 1px solid var(--border); border-radius: 7px; background: var(--bg);
}
.foundation-box small, .foundation-compare small { color: var(--text-3); font-size: 10px; font-weight: 500; }
.foundation-box b {
  color: currentColor; font-size: 11px; font-weight: 650; line-height: 1.35;
  overflow-wrap: anywhere;
}
.foundation-code {
  display: flex; width: 100%; min-width: 0; flex-direction: column; gap: 3px; padding: 8px 10px;
  overflow: hidden; border: 1px solid #243044; border-radius: 7px; background: #111827;
  color: #d5def0; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 10px;
}
.foundation-code span { overflow-wrap: anywhere; }
.foundation-code em { color: #8390a7; font-style: normal; }
.foundation-code b { color: #9cc2ff; font-weight: 650; }
.foundation-code b.success { color: #79d6a3; }
.foundation-code b.danger { color: #ff9f9f; }
.foundation-compare {
  display: grid; width: 100%; min-width: 0; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: stretch; gap: 6px;
}
.foundation-compare > span {
  display: flex; min-width: 0; flex-direction: column; justify-content: center; gap: 3px;
  padding: 7px 8px; border: 1px solid var(--border); border-radius: 7px; background: var(--bg);
}
.foundation-compare > span.green,
.foundation-compare > span.red { border-color: var(--border); background: var(--bg); }
.foundation-compare > span.green b { color: var(--green); }
.foundation-compare > span.red b { color: var(--red); }
.foundation-compare b {
  color: var(--text); font-size: 11px; line-height: 1.35; overflow-wrap: anywhere;
}
.foundation-compare > i { align-self: center; color: var(--text-3); font-size: 11px; font-style: normal; }

/* 典型使用场景中的完整界面，比 use / don't 配图更接近真实产品。 */
.foundation-scene-ui {
  width: min(100%, 720px); margin: 0 auto; overflow: hidden;
  border: 0; border-radius: 0; background: var(--bg);
}
.scene-shot:has(.foundation-scene-ui) .sc-bar { display: none; }
.scene-shot:has(.foundation-scene-ui) .sc-body { min-height: 0; padding: 0; }
.foundation-scene-ui-head {
  display: flex; flex-direction: column; gap: 3px; padding: 12px 16px;
  border-bottom: 1px solid var(--border-light); background: var(--bg-soft);
}
.foundation-scene-ui-head span {
  color: var(--brand); font-size: 10px; font-weight: 700; letter-spacing: .7px; text-transform: uppercase;
}
.foundation-scene-ui-head b { color: var(--text); font-size: 14px; }
.foundation-scene-ui-body {
  display: flex; min-height: 96px; align-items: center; justify-content: center; padding: 16px;
}
.foundation-scene-ui-foot {
  padding: 9px 16px; border-top: 1px solid var(--border-light);
  color: var(--text-3); font-size: 11px; line-height: 1.5;
}
.foundation-scene-ui .foundation-boxes,
.foundation-scene-ui .foundation-compare,
.foundation-scene-ui .foundation-code { max-width: 620px; }
.foundation-scene-ui .foundation-box { min-height: 52px; justify-content: center; }
.foundation-scene-ui .foundation-box small,
.foundation-scene-ui .foundation-compare small { font-size: 11px; }
.foundation-scene-ui .foundation-box b,
.foundation-scene-ui .foundation-compare b { font-size: 12px; }
.foundation-scene-ui .foundation-step { min-height: 30px; padding: 5px 10px; font-size: 12px; }
.foundation-scene-ui .foundation-code { padding: 12px 14px; font-size: 11px; line-height: 1.55; }
.foundation-ui-hero {
  display: flex; max-width: 520px; flex-direction: column; align-items: flex-start; gap: 8px; text-align: left;
}
.foundation-ui-hero > .foundation-ui-kicker { color: var(--brand); font-size: 10px; font-weight: 700; letter-spacing: 1px; }
.foundation-ui-hero h3 { margin: 0; color: var(--text); font-size: 22px; line-height: 1.2; }
.foundation-ui-hero p { margin: 0; color: var(--text-2); font-size: 12px; }
.foundation-ui-form {
  display: flex; width: min(100%, 440px); flex-direction: column; align-items: stretch; gap: 9px;
}
.foundation-ui-field { display: flex; flex-direction: column; gap: 4px; }
.foundation-ui-field > span { color: var(--text-2); font-size: 11px; }
.foundation-ui-field > b {
  min-height: 34px; padding: 8px 10px; border: 1px solid var(--border); border-radius: 7px;
  background: var(--bg); color: var(--text); font-size: 12px; font-weight: 500;
}
.foundation-ui-field.error > b {
  border-color: color-mix(in srgb, var(--red) 55%, var(--border));
  background: var(--red-light); color: var(--red);
}
.foundation-ui-action {
  display: inline-flex; min-height: 32px; align-items: center; justify-content: center; align-self: flex-start;
  padding: 6px 12px; border: 1px solid transparent; border-radius: 7px;
  background: var(--brand); color: var(--on-brand); font-size: 12px; font-weight: 650;
}
.foundation-ui-action.red { background: var(--red); }
.foundation-ui-action.neutral { border-color: var(--border); background: var(--bg); color: var(--text-2); }

@media (max-width: 720px) {
  .stack-front-page { grid-template-columns: minmax(0, 1fr) 72px; }
  .stack-back-pipeline { grid-template-columns: 1fr; }
  .stack-back-pipeline > em { display: none; }
  .stack-back-pipeline > span { min-height: 48px; }
  .frontend-anat { grid-template-columns: 1fr; }
  .frontend-anat-screen { grid-column: 1; }
  .foundation-boxes { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .foundation-scene-ui-head { padding: 10px 12px; }
  .foundation-scene-ui-body { min-height: 84px; padding: 12px; }
  .foundation-scene-ui-foot { padding: 8px 12px; }
  .foundation-ui-hero h3 { font-size: 18px; }
}

/* ---- Serverless：请求触发函数 ---- */
.sl-demo { display: flex; align-items: center; justify-content: center; gap: 8px; flex-wrap: wrap; width: 100%; }
.sl-io {
  display: grid;
  justify-items: center;
  gap: 2px;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
}
.sl-io small { color: var(--text-3); font-size: 10px; }
.sl-io b { color: var(--text-2); font: 600 11px/1.3 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }
.sl-arrow { color: var(--text-3); font-size: 12px; font-style: normal; }
.sl-fn {
  display: grid;
  justify-items: center;
  gap: 2px;
  padding: 8px 14px;
  border: 1px solid color-mix(in srgb, var(--brand) 34%, var(--border));
  border-radius: 8px;
  background: var(--brand-light);
}
.sl-fn b { color: var(--brand); font-size: 12px; }
.sl-fn small { color: var(--text-3); font-size: 10px; }
.sl-note { flex-basis: 100%; color: var(--text-3); font-size: 11px; text-align: center; }

/* ---- 后端框架：请求经过的三段骨架 ---- */
.fw-demo,
.route-demo,
.sql-demo,
.val-demo,
.auth-demo,
.az-demo {
  display: grid;
  gap: 10px;
  width: 100%;
  max-width: 360px;
}
.fw-pipe {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: stretch;
  gap: 4px;
}
.fw-pipe > i,
.fw-anat > i,
.val-anat > i,
.auth-anat > i,
.auth-flow > i {
  align-self: center;
  color: var(--text-3);
  font-size: 12px;
  font-style: normal;
}
.fw-step,
.fw-anat-step {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: 8px 7px;
  border: 1px solid var(--border-light);
  border-radius: 8px;
  background: var(--bg);
  text-align: center;
}
.fw-step small,
.fw-anat-step small { color: var(--text-3); font-size: 10px; }
.fw-step b,
.fw-anat-step b { color: var(--text); font-size: 12px; }
.fw-step em {
  color: var(--text-3);
  font-size: 10px;
  font-style: normal;
  line-height: 1.3;
  overflow-wrap: anywhere;
}
.fw-step.on,
.fw-anat-step.on {
  border-color: color-mix(in srgb, var(--brand) 30%, var(--border));
  background: var(--brand-light);
}
.fw-step.on b,
.fw-anat-step.on b { color: var(--brand); }
.fw-note,
.route-note {
  color: var(--text-3);
  font-size: 11px;
  text-align: center;
  line-height: 1.4;
}
.fw-anat {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 6px;
}
.fw-variant {
  color: var(--text-2);
  font-size: 12px;
}

/* ---- 路由：方法 + 路径 → 处理函数 ---- */
.route-board {
  display: grid;
  gap: 6px;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg);
}
.route-row {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding: 6px 8px;
  border: 1px solid transparent;
  border-radius: 7px;
  background: var(--bg-soft);
}
.route-row.on {
  border-color: color-mix(in srgb, var(--brand) 28%, var(--border));
  background: color-mix(in srgb, var(--brand-light) 55%, var(--bg));
}
.route-row b,
.m-get, .m-post, .m-patch, .m-del {
  display: inline-grid;
  place-items: center;
  min-width: 44px;
  min-height: 20px;
  border-radius: 4px;
  color: #fff;
  font-size: 10px;
  font-weight: 750;
  letter-spacing: .02em;
}
.route-row b.m-get, .m-get { background: var(--green); color: var(--on-status); }
.route-row b.m-post, .m-post { background: var(--brand); color: var(--on-brand); }
.m-patch { background: var(--warning); color: var(--on-status); }
.m-del { background: #dc2626; }
.route-row code {
  min-width: 0;
  overflow: hidden;
  color: var(--text);
  font: 600 11px/1.3 ui-monospace, SFMono-Regular, Menlo, monospace;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.route-row span { color: var(--text-3); font-size: 11px; white-space: nowrap; }
.route-anat {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}
.route-piece {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 4px 8px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
}
.route-piece.path { color: var(--text); background: var(--bg-soft); }
.route-piece.query { color: var(--text-3); background: var(--bg-soft); }

/* ---- SQL：语句命中表格行 ---- */
.sql-demo { max-width: 320px; }
.sql-query {
  display: grid;
  gap: 2px;
  padding: 10px 12px;
  border: 1px solid #243044;
  border-radius: 10px;
  background: #171a22;
  color: #dbe4ff;
  font: 500 12px/1.55 ui-monospace, SFMono-Regular, Menlo, monospace;
  text-align: left;
}
.sql-query b { color: #93c5fd; font-weight: 700; }
.sql-query.compact { padding: 8px 10px; font-size: 11px; }
.sql-bridge {
  display: flex;
  justify-content: center;
}
.sql-bridge span {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 0 8px;
  border-radius: 999px;
  color: var(--brand);
  background: var(--brand-light);
  font-size: 11px;
  font-weight: 650;
}
.sql-table {
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg);
  font-size: 12px;
}
.sql-head,
.sql-row {
  display: grid;
  grid-template-columns: 32px 1fr 1fr;
}
.sql-head span,
.sql-row span {
  padding: 6px 8px;
  border-bottom: 1px solid var(--border-light);
}
.sql-head span {
  color: var(--text-3);
  background: var(--bg-soft);
  font-size: 11px;
  font-weight: 700;
}
.sql-row span { color: var(--text-2); }
.sql-row:last-child span { border-bottom: 0; }
.sql-row.hit span {
  color: var(--text);
  background: color-mix(in srgb, var(--brand) 10%, var(--bg));
  font-weight: 650;
}
.sql-row.dim span { color: var(--text-3); opacity: .72; }
.sql-anat { display: grid; gap: 8px; width: min(100%, 320px); }
.sql-variant {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-2);
}

/* ---- 数据校验：字段通过 / 失败 ---- */
.val-form {
  display: grid;
  gap: 6px;
  padding: 10px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg);
}
.val-form label {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  padding: 6px 8px;
  border: 1px solid var(--border-light);
  border-radius: 8px;
  background: var(--bg-soft);
}
.val-form label > span { color: var(--text-3); font-size: 11px; }
.val-form label > b {
  min-width: 0;
  color: var(--text);
  font-size: 12px;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.val-form label > i {
  font-size: 11px;
  font-style: normal;
  font-weight: 700;
  white-space: nowrap;
}
.val-form label.ok { border-color: color-mix(in srgb, var(--green) 30%, var(--border)); }
.val-form label.ok > i { color: color-mix(in srgb, var(--green) 80%, var(--text)); }
.val-form label.bad {
  border-color: color-mix(in srgb, var(--red) 34%, var(--border));
  background: color-mix(in srgb, var(--red) 6%, var(--bg));
}
.val-form label.bad > b,
.val-form label.bad > i { color: var(--red); }
.val-gate {
  display: grid;
  gap: 2px;
  justify-items: center;
  padding: 8px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--red) 7%, var(--bg));
  border: 1px solid color-mix(in srgb, var(--red) 22%, var(--border));
  text-align: center;
}
.val-gate small { color: var(--text-3); font-size: 10px; }
.val-gate strong { color: var(--red); font-size: 12px; }
.val-anat {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 6px;
}
.val-piece,
.auth-piece,
.az-piece {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 4px 9px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg);
  color: var(--text-2);
  font-size: 12px;
  font-weight: 650;
}
.val-piece.rules,
.auth-piece.on { border-color: color-mix(in srgb, var(--brand) 28%, var(--border)); color: var(--brand); background: var(--brand-light); }
.val-piece.ok,
.auth-piece.ok { border-color: color-mix(in srgb, var(--green) 30%, var(--border)); color: color-mix(in srgb, var(--green) 78%, var(--text)); background: color-mix(in srgb, var(--green) 8%, var(--bg)); }
.val-piece.bad { border-color: color-mix(in srgb, var(--red) 30%, var(--border)); color: var(--red); background: color-mix(in srgb, var(--red) 6%, var(--bg)); }
.val-or { color: var(--text-3); font-size: 11px; }

/* ---- 身份认证：登录卡 + 三步 ---- */
.auth-card {
  display: grid;
  gap: 8px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg);
  box-shadow: 0 8px 20px color-mix(in srgb, var(--text) 5%, transparent);
}
.auth-card label {
  display: grid;
  gap: 4px;
}
.auth-card label > span { color: var(--text-3); font-size: 11px; }
.auth-card label > b {
  min-height: 32px;
  padding: 7px 9px;
  border: 1px solid var(--border);
  border-radius: 7px;
  color: var(--text);
  background: var(--bg-soft);
  font-size: 12px;
  font-weight: 500;
}
.auth-card button {
  min-height: 34px;
  border: 0;
  border-radius: 8px;
  color: var(--on-brand);
  background: var(--brand);
  font-size: 12px;
  font-weight: 700;
  cursor: default;
}
.auth-flow,
.auth-anat {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 6px;
}
.auth-flow span {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 3px 8px;
  border: 1px solid var(--border-light);
  border-radius: 999px;
  color: var(--text-3);
  background: var(--bg);
  font-size: 11px;
  font-weight: 650;
}
.auth-flow span.on { color: var(--brand); border-color: color-mix(in srgb, var(--brand) 28%, var(--border)); background: var(--brand-light); }
.auth-flow span.ok { color: color-mix(in srgb, var(--green) 78%, var(--text)); border-color: color-mix(in srgb, var(--green) 28%, var(--border)); background: color-mix(in srgb, var(--green) 8%, var(--bg)); }
.auth-variant {
  color: var(--text-2);
  font-size: 12px;
}
.auth-variant code {
  font: 600 11px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace;
}

/* ---- 权限控制：允许 / 拒绝矩阵 ---- */
.az-who {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg-soft);
}
.az-who small { color: var(--text-3); font-size: 11px; }
.az-who b { color: var(--text); font-size: 12px; }
.az-matrix {
  display: grid;
  gap: 4px;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg);
}
.az-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  min-height: 30px;
  padding: 5px 8px;
  border-radius: 6px;
  background: var(--bg-soft);
  font-size: 12px;
}
.az-row span { color: var(--text-2); }
.az-row em {
  min-width: 40px;
  padding: 2px 7px;
  border-radius: 999px;
  font-size: 11px;
  font-style: normal;
  font-weight: 750;
  text-align: center;
}
.az-row em.ok {
  color: color-mix(in srgb, var(--green) 78%, var(--text));
  background: color-mix(in srgb, var(--green) 10%, var(--bg));
}
.az-row em.no {
  color: var(--red);
  background: color-mix(in srgb, var(--red) 8%, var(--bg));
}
.az-anat {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 6px;
}
.az-can { color: var(--text-3); font-size: 11px; }
.az-piece.action { color: var(--brand); border-color: color-mix(in srgb, var(--brand) 28%, var(--border)); background: var(--brand-light); }
.az-piece.resource { color: color-mix(in srgb, var(--green) 72%, var(--text)); border-color: color-mix(in srgb, var(--green) 28%, var(--border)); background: color-mix(in srgb, var(--green) 8%, var(--bg)); }
.az-variant {
  color: var(--text-2);
  font-size: 12px;
}
.az-variant.mono {
  font: 600 11px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace;
}

.dh-demo .fw-demo,
.dh-demo .route-demo,
.dh-demo .sql-demo,
.dh-demo .val-demo,
.dh-demo .auth-demo,
.dh-demo .az-demo { max-width: 420px; }
.dh-demo .fw-step { min-height: 78px; padding: 12px 10px; }
.dh-demo .sql-query { font-size: 13px; padding: 14px 16px; }
.dh-demo .auth-card { padding: 16px; }

@media (min-width: 721px) {
  .detail-hero .dh-demo :is(
    .fw-demo,
    .route-demo,
    .sql-demo,
    .val-demo,
    .auth-demo,
    .az-demo
  ) {
    width: 100%;
    max-width: none;
  }
  .detail-hero .dh-demo .fw-step { min-height: 104px; }
  .detail-hero .dh-demo .sql-demo {
    grid-template-columns: minmax(0, .9fr) auto minmax(0, 1.1fr);
    align-items: stretch;
  }
  .detail-hero .dh-demo .sql-bridge { align-items: center; }
  .detail-hero .dh-demo .val-demo {
    grid-template-columns: minmax(0, 1.35fr) minmax(220px, .75fr);
    align-items: stretch;
  }
  .detail-hero .dh-demo .auth-demo {
    grid-template-columns: minmax(280px, .85fr) minmax(0, 1.15fr);
    align-items: center;
    gap: 28px;
  }
  .detail-hero .dh-demo .auth-flow {
    flex-wrap: nowrap;
    justify-content: space-between;
  }
  .detail-hero .dh-demo .az-demo {
    grid-template-columns: minmax(190px, .6fr) minmax(0, 1.4fr);
    align-items: stretch;
    gap: 18px;
  }
  .detail-hero .dh-demo .az-who {
    flex-direction: column;
    align-items: flex-start;
    justify-content: center;
  }
}

@media (max-width: 720px) {
  .fw-demo,
  .route-demo,
  .sql-demo,
  .val-demo,
  .auth-demo,
  .az-demo {
    max-width: 100%;
  }
  .fw-pipe {
    grid-template-columns: minmax(0, 1fr);
    gap: 6px;
  }
  .fw-pipe > i { justify-self: center; transform: rotate(90deg); }
  .fw-step { min-height: 0; }
  .route-row {
    grid-template-columns: 48px minmax(0, 1fr);
  }
  .route-row span {
    grid-column: 2;
    white-space: normal;
  }
  .sql-query { font-size: 11px; padding: 10px; }
  .sql-head,
  .sql-row { grid-template-columns: 28px minmax(0, 1fr) minmax(0, 1fr); }
  .val-form label {
    grid-template-columns: 40px minmax(0, 1fr);
    gap: 4px 8px;
  }
  .val-form label > i {
    grid-column: 2;
    justify-self: start;
  }
  .auth-card { padding: 10px; }
  .auth-flow { gap: 4px; }
  .auth-flow span { font-size: 10px; padding: 3px 6px; }
  .az-who { flex-wrap: wrap; }
  .dh-demo .fw-step { min-height: 0; padding: 10px 8px; }
}

/* ---- 基础概念目录卡片：保留详情图里的核心关系 ---- */

.foundation-card-visual {
  width: min(420px, 100%);
  min-width: 0;
  color: var(--text);
  font-size: 11px;
}

.foundation-card-visual *,
.foundation-card-visual *::before,
.foundation-card-visual *::after {
  box-sizing: border-box;
}

.foundation-card-visual code,
.foundation-card-visual button,
.foundation-card-visual input {
  font: inherit;
}

.foundation-card-visual button {
  border: 0;
  cursor: default;
}

.fc-foot {
  color: var(--text-3);
  font-size: 10px;
  line-height: 1.35;
  text-align: center;
}

/* Component */
.fc-component {
  display: grid;
  grid-template-columns: minmax(112px, 0.72fr) minmax(0, 1.28fr);
  gap: 9px 12px;
  align-items: center;
}
.fc-component-source {
  display: grid;
  gap: 4px;
  padding: 11px;
  border: 1px solid color-mix(in srgb, var(--brand) 35%, var(--border));
  border-radius: 9px;
  background: var(--brand-light);
}
.fc-component-source small,
.fc-component-pages small {
  color: var(--text-3);
  font-size: 9px;
}
.fc-component-source b {
  color: var(--brand);
  font-size: 13px;
}
.fc-component-source code {
  color: var(--text-2);
  font-size: 9px;
}
.fc-component-pages {
  display: grid;
  grid-template-columns: 1fr 12px 1fr;
  align-items: center;
  gap: 4px;
}
.fc-component-pages span {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 10px 8px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
}
.fc-component-pages span b {
  overflow: hidden;
  font-size: 9px;
  text-overflow: ellipsis;
}
.fc-component-pages i {
  height: 1px;
  background: var(--brand);
}
.fc-component .fc-foot {
  grid-column: 1 / -1;
}

/* State */
.fc-state {
  display: grid;
  gap: 9px;
}
.fc-state-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 8px;
  padding: 9px 11px;
  border: 1px solid var(--border);
  border-radius: 9px;
  background: var(--bg);
}
.fc-state-form small {
  grid-column: 1 / -1;
  color: var(--text-3);
  font-size: 9px;
}
.fc-state-form b {
  align-self: center;
}
.fc-state-form button {
  padding: 4px 8px;
  border-radius: 6px;
  color: var(--green);
  background: var(--green-light);
}
.fc-state-track {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  flex-wrap: wrap;
}
.fc-state-track span {
  padding: 4px 6px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  white-space: nowrap;
}
.fc-state-track i,
.fc-state-track em {
  color: var(--text-3);
  font-size: 9px;
  font-style: normal;
}
.fc-state-track .ok {
  border-color: color-mix(in srgb, var(--green) 35%, var(--border));
  color: var(--green);
  background: var(--green-light);
}
.fc-state-track .fail {
  color: var(--red);
  background: var(--red-light);
}

/* Port */
.fc-port {
  display: grid;
  gap: 8px;
}
.fc-port-address {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
}
.fc-port-address code {
  padding: 5px 9px;
  border-radius: 6px;
  color: var(--brand);
  background: var(--brand-light);
  font-weight: 700;
}
.fc-port-address b {
  color: var(--text-2);
  font-size: 10px;
}
.fc-port-sockets {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
}
.fc-port-sockets span {
  display: grid;
  justify-items: center;
  gap: 4px;
  padding: 9px 5px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
}
.fc-port-sockets span.active {
  border-color: color-mix(in srgb, var(--brand) 42%, var(--border));
  background: var(--brand-light);
}
.fc-port-sockets code {
  color: var(--brand);
  font-weight: 700;
}
.fc-port-sockets b {
  color: var(--text-2);
  font-size: 10px;
}

/* Box model */
.fc-box-model {
  display: grid;
  grid-template-columns: minmax(155px, 1.15fr) minmax(110px, 0.85fr);
  align-items: center;
  gap: 8px 14px;
}
.fc-box-layers span {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  font-size: 9px;
}
.fc-box-layers .margin {
  padding: 6px;
  border: 1px dashed var(--border);
  color: var(--text-3);
  background: var(--bg-soft);
}
.fc-box-layers .border {
  padding: 6px;
  color: var(--text-2);
  background: var(--text-2);
}
.fc-box-layers .padding {
  padding: 9px;
  color: var(--brand);
  background: var(--brand-light);
}
.fc-box-layers b {
  width: 100%;
  padding: 9px 5px;
  color: var(--text);
  background: var(--bg);
  font-size: 10px;
  text-align: center;
}
.fc-box-equation {
  display: grid;
  justify-items: center;
  gap: 6px;
}
.fc-box-equation code {
  color: var(--text-3);
  font-size: 10px;
}
.fc-box-equation strong {
  color: var(--brand);
  font-size: 18px;
}
.fc-box-model .fc-foot {
  grid-column: 1 / -1;
}

/* Overflow */
.fc-overflow {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(105px, 0.7fr);
  align-items: center;
  gap: 12px;
}
.fc-overflow-window {
  position: relative;
  height: 78px;
  overflow: hidden;
  display: grid;
  gap: 3px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
}
.fc-overflow-window small {
  color: var(--red);
  font-size: 8px;
}
.fc-overflow-window span {
  color: var(--text-2);
  font-size: 9px;
}
.fc-overflow-window button {
  justify-self: start;
  margin-top: 3px;
  padding: 5px 8px;
  border-radius: 5px;
  color: white;
  background: var(--brand);
}
.fc-overflow-window i {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 13px;
  border-top: 1px dashed var(--red);
  color: var(--red);
  background: color-mix(in srgb, var(--red-light) 88%, transparent);
  font-size: 8px;
  font-style: normal;
  text-align: right;
}
.fc-overflow-note {
  display: grid;
  gap: 6px;
  text-align: center;
}
.fc-overflow-note span {
  padding: 5px;
  border-radius: 6px;
  font-size: 9px;
}
.fc-overflow-note .fail {
  color: var(--red);
  background: var(--red-light);
}
.fc-overflow-note .ok {
  color: var(--green);
  background: var(--green-light);
}
.fc-overflow-note b {
  color: var(--text-3);
}

/* CORS */
.fc-cors {
  display: grid;
  gap: 8px;
}
.fc-cors-request {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 7px;
}
.fc-cors-request span {
  display: grid;
  gap: 3px;
  min-width: 0;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  text-align: center;
}
.fc-cors-request small {
  color: var(--text-3);
  font-size: 9px;
}
.fc-cors-request b {
  overflow: hidden;
  font-size: 10px;
  text-overflow: ellipsis;
}
.fc-cors-request i {
  color: var(--brand);
  font-style: normal;
}
.fc-cors-response {
  display: flex;
  align-items: center;
  gap: 7px;
}
.fc-cors-response code {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  padding: 6px 8px;
  border-radius: 6px;
  color: var(--brand);
  background: var(--brand-light);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.fc-cors-response .ok {
  color: var(--green);
  font-size: 9px;
  white-space: nowrap;
}

/* Browser storage */
.fc-storage {
  display: grid;
  gap: 8px;
}
.fc-storage-devices {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 7px;
}
.fc-storage-devices section {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 8px;
  border: 1px solid color-mix(in srgb, var(--brand) 35%, var(--border));
  border-radius: 8px;
  background: var(--brand-light);
}
.fc-storage-devices section.empty {
  border-color: var(--border);
  background: var(--bg);
}
.fc-storage-devices small {
  color: var(--text-3);
  font-size: 9px;
}
.fc-storage-devices b,
.fc-storage-devices code {
  overflow: hidden;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.fc-storage-devices > i {
  color: var(--red);
  font-size: 9px;
  font-style: normal;
  text-align: center;
}
.fc-storage-server {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 8px;
  color: var(--text-3);
  font-size: 9px;
  text-align: center;
}
.fc-storage-server b {
  padding: 5px 8px;
  border-radius: 6px;
  color: var(--green);
  background: var(--green-light);
  font-size: 10px;
}

/* SEO */
.fc-seo {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: 8px 12px;
  align-items: center;
}
.fc-seo article,
.fc-seo-result {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 9px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
}
.fc-seo small {
  color: var(--text-3);
  font-size: 9px;
}
.fc-seo article span {
  color: var(--text-2);
  font-size: 9px;
  line-height: 1.4;
}
.fc-seo-result a {
  color: var(--brand);
  font-size: 11px;
  font-weight: 650;
}
.fc-seo-result code {
  color: var(--green);
  font-size: 9px;
}
.fc-seo .fc-foot {
  grid-column: 1 / -1;
}

/* Redirect */
.fc-redirect {
  display: grid;
  gap: 8px;
}
.fc-redirect-bar {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 8px;
  padding: 6px 9px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg);
}
.fc-redirect-bar small {
  color: var(--text-3);
  font-size: 9px;
}
.fc-redirect-bar code {
  overflow: hidden;
  color: var(--text-2);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.fc-redirect-network {
  display: flex;
  align-items: stretch;
  justify-content: center;
  gap: 5px;
}
.fc-redirect-network span {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: 6px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
}
.fc-redirect-network span.location {
  border-color: color-mix(in srgb, var(--brand) 35%, var(--border));
  background: var(--brand-light);
}
.fc-redirect-network span.ok {
  border-color: color-mix(in srgb, var(--green) 35%, var(--border));
  background: var(--green-light);
}
.fc-redirect-network span b {
  font-size: 9px;
}
.fc-redirect-network span code {
  overflow: hidden;
  color: var(--text-3);
  font-size: 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.fc-redirect-network > i {
  align-self: center;
  color: var(--brand);
  font-size: 9px;
  font-style: normal;
}

/* Chat UI */
.fc-chat {
  overflow: hidden;
  display: grid;
  border: 1px solid var(--border);
  border-radius: 9px;
  background: var(--bg);
}
.fc-chat-head {
  display: flex;
  justify-content: space-between;
  padding: 6px 9px;
  border-bottom: 1px solid var(--border-light);
}
.fc-chat-head small {
  color: var(--green);
  font-size: 9px;
}
.fc-chat-messages {
  display: grid;
  gap: 4px;
  padding: 7px 9px;
}
.fc-chat-messages p {
  width: fit-content;
  max-width: 82%;
  margin: 0;
  padding: 4px 7px;
  border-radius: 6px;
  color: var(--text-2);
  background: var(--bg-soft);
  font-size: 9px;
}
.fc-chat-messages p.user {
  justify-self: end;
  color: var(--brand);
  background: var(--brand-light);
}
.fc-chat-messages p.error {
  color: var(--red);
  background: var(--red-light);
}
.fc-chat-input {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 8px;
  border-top: 1px solid var(--border-light);
  color: var(--text-3);
  font-size: 9px;
}
.fc-chat-input button {
  padding: 4px 7px;
  border-radius: 5px;
  color: white;
  background: var(--brand);
}

/* Responsive design */
.fc-responsive {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) auto minmax(80px, 0.65fr);
  align-items: center;
  gap: 7px;
}
.fc-responsive > b {
  color: var(--brand);
  font-size: 9px;
  font-weight: 600;
}
.fc-responsive-view {
  overflow: hidden;
  display: grid;
  gap: 4px;
  padding: 5px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg);
}
.fc-responsive-view > small {
  color: var(--text-3);
  font-size: 8px;
}
.fc-responsive-view header {
  padding: 4px;
  color: white;
  background: var(--text);
  font-size: 8px;
  white-space: nowrap;
}
.fc-responsive-view section {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3px;
}
.fc-responsive-view section i {
  height: 36px;
  border-radius: 3px;
  background: var(--brand-light);
}
.fc-responsive-view.mobile section {
  grid-template-columns: 1fr;
}
.fc-responsive-view.mobile section i {
  height: 10px;
}
.fc-responsive .fc-foot {
  grid-column: 1 / -1;
}

/* Search */
.fc-search {
  display: grid;
  gap: 7px;
}
.fc-search-input {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  border: 1px solid color-mix(in srgb, var(--brand) 40%, var(--border));
  border-radius: 8px;
  background: var(--bg);
}
.fc-search-input span {
  color: var(--brand);
  font-size: 15px;
}
.fc-search-input i {
  color: var(--text-3);
  font-style: normal;
}
.fc-search-results {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
}
.fc-search-results article {
  display: grid;
  gap: 3px;
  padding: 7px 9px;
  border-radius: 7px;
  background: var(--bg-soft);
}
.fc-search-results small {
  color: var(--text-3);
  font-size: 9px;
}
.fc-search-results mark {
  color: var(--brand);
  background: color-mix(in srgb, var(--brand-light) 65%, transparent);
}

/* Filter */
.fc-filter {
  display: grid;
  gap: 7px;
}
.fc-filter-controls {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}
.fc-filter-controls span {
  padding: 4px 7px;
  border-radius: 999px;
  color: var(--brand);
  background: var(--brand-light);
  font-size: 9px;
}
.fc-filter-controls button {
  margin-left: auto;
  color: var(--text-3);
  background: transparent;
  font-size: 9px;
}
.fc-filter-list {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  padding-right: 48px;
}
.fc-filter-list article {
  display: grid;
  gap: 3px;
  padding: 7px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg);
}
.fc-filter-list small {
  color: var(--text-3);
  font-size: 9px;
}
.fc-filter-list > i {
  position: absolute;
  top: 50%;
  right: 0;
  color: var(--brand);
  font-size: 9px;
  font-style: normal;
  transform: translateY(-50%);
}

/* Chart */
.fc-chart {
  display: grid;
  gap: 6px;
}
.fc-chart-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.fc-chart-head small {
  color: var(--text-3);
  font-size: 9px;
}
.fc-chart-bars {
  height: 76px;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  align-items: end;
  gap: 6px;
  padding: 5px 8px 0;
  border-bottom: 1px solid var(--border);
}
.fc-chart-bars span {
  position: relative;
  height: 100%;
  display: grid;
  grid-template-rows: 1fr auto;
  justify-items: center;
  align-items: end;
  gap: 3px;
}
.fc-chart-bars span i {
  width: 70%;
  height: var(--v);
  border-radius: 3px 3px 0 0;
  background: color-mix(in srgb, var(--brand) 35%, var(--bg-soft));
}
.fc-chart-bars span.max i {
  background: var(--brand);
}
.fc-chart-bars small {
  color: var(--text-3);
  font-size: 8px;
}
.fc-chart-bars span b {
  position: absolute;
  top: 0;
  color: var(--brand);
  font-size: 9px;
}

/* Dark mode */
.fc-dark-mode {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 7px;
}
.fc-dark-mode > i {
  color: var(--brand);
  font-style: normal;
}
.fc-theme {
  display: grid;
  gap: 5px;
  padding: 9px;
  border: 1px solid #d8dce5;
  border-radius: 8px;
  color: #20232b;
  background: var(--bg);
}
.fc-theme small {
  color: #6b7280;
  font-size: 9px;
}
.fc-theme span {
  font-size: 9px;
}
.fc-theme button {
  justify-self: start;
  padding: 4px 7px;
  border-radius: 5px;
  color: #fff;
  background: #3156d3;
}
.fc-theme.dark {
  border-color: #3d4452;
  color: #f3f4f6;
  background: #171a21;
}
.fc-theme.dark small,
.fc-theme.dark span {
  color: #aeb4c0;
}
.fc-dark-mode .fc-foot {
  grid-column: 1 / -1;
}

/* Design token */
.fc-design-token {
  display: grid;
  gap: 0;
}
.fc-token-source {
  justify-self: center;
  display: grid;
  gap: 3px;
  padding: 6px 10px;
  border: 1px solid color-mix(in srgb, var(--brand) 35%, var(--border));
  border-radius: 7px;
  background: var(--brand-light);
}
.fc-token-source small {
  color: var(--text-3);
  font-size: 8px;
}
.fc-token-source code {
  color: var(--brand);
  font-size: 9px;
  font-weight: 700;
}
.fc-token-links {
  width: 68%;
  height: 15px;
  justify-self: center;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}
.fc-token-links i {
  border-top: 1px solid var(--brand);
  border-left: 1px solid var(--brand);
}
.fc-token-links i:last-child {
  border-right: 1px solid var(--brand);
}
.fc-token-components {
  display: grid;
  grid-template-columns: 0.75fr 1fr 1fr;
  align-items: stretch;
  gap: 6px;
}
.fc-token-components button,
.fc-token-components label,
.fc-token-components article {
  min-width: 0;
  padding: 7px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg);
}
.fc-token-components button {
  align-self: center;
  color: white;
  background: var(--brand);
}
.fc-token-components label {
  display: grid;
  gap: 3px;
  color: var(--text-3);
  font-size: 8px;
}
.fc-token-components input {
  min-width: 0;
  width: 100%;
  border: 0;
  color: var(--text);
  background: transparent;
  font-size: 9px;
}
.fc-token-components article {
  display: grid;
  gap: 3px;
  border-color: var(--brand);
}
.fc-token-components article small {
  color: var(--brand);
  font-size: 8px;
}
.fc-token-components article b {
  overflow: hidden;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.fc-design-token .fc-foot {
  margin-top: 6px;
}

@media (max-width: 560px) {
  .fc-component,
  .fc-box-model,
  .fc-overflow,
  .fc-seo {
    grid-template-columns: minmax(0, 1fr);
  }
  .fc-component .fc-foot,
  .fc-box-model .fc-foot,
  .fc-seo .fc-foot {
    grid-column: 1;
  }
  .fc-overflow-note {
    grid-template-columns: 1fr auto 1fr;
    align-items: center;
  }
  .fc-redirect-network {
    gap: 3px;
  }
  .fc-redirect-network span {
    padding: 5px 3px;
  }
}

/* Server log */
.server-log-mini {
  width: min(420px, 100%);
  overflow: hidden;
  display: grid;
  border: 1px solid var(--border);
  border-radius: 9px;
  color: var(--text);
  background: var(--bg);
  font: 10px/1.35 ui-monospace, SFMono-Regular, Menlo, monospace;
}
.server-log-mini-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 9px;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-soft);
}
.server-log-mini-head code { color: var(--brand); }
.server-log-mini-lines { display: grid; padding: 5px 9px; }
.server-log-mini-lines span {
  display: grid;
  grid-template-columns: 52px minmax(80px, 1fr) minmax(90px, 1.2fr);
  gap: 7px;
  padding: 4px 0;
  color: var(--text-2);
  border-bottom: 1px solid var(--border-light);
}
.server-log-mini-lines span:last-child { border-bottom: 0; }
.server-log-mini-lines i { color: var(--text-3); font-style: normal; }
.server-log-mini-lines code {
  overflow: hidden;
  color: var(--brand);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.server-log-mini-lines .ok b,
.server-log-mini-lines .ok code { color: var(--green); }
.server-log-mini > small {
  padding: 5px 9px;
  color: var(--text-3);
  background: var(--bg-soft);
  text-align: center;
}

/* domains/platform/testing-delivery.css */
/* 测试与交付：图解使用真实业务界面，不使用通用概念卡片。 */
.testing-visual {
  --td-ink: var(--text);
  --td-muted: var(--text-2);
  --td-faint: var(--bg-soft);
  --td-line: var(--border);
  --td-pass: var(--green);
  --td-pass-soft: var(--green-light);
  --td-blue: var(--info);
  --td-blue-soft: var(--info-light);
  --td-alert: var(--red);
  --td-alert-soft: var(--red-light);
  width: 100%;
  color: var(--td-ink);
}
.td-stage { outline: none; }
.td-stage:focus-visible { outline: 3px solid #9eb8ef; outline-offset: 6px; border-radius: 8px; }
.td-controls { display: flex; gap: 24px; margin: 0 0 22px; border-bottom: 1px solid var(--td-line); }
.td-controls button {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 46px;
  padding: 0 0 12px;
  border: 0;
  border-bottom: 2px solid transparent;
  color: var(--td-muted);
  background: transparent;
  font: 620 15px/1.3 ui-sans-serif, system-ui, sans-serif;
  cursor: pointer;
}
.td-controls button span { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; color: var(--td-muted); background: var(--bg-hover); font-size: 13px; }
.td-controls button:hover, .td-controls button:focus-visible { color: var(--td-ink); }
.td-controls button:focus-visible { outline: 2px solid #9eb8ef; outline-offset: 4px; }
.td-controls button.is-active { color: var(--td-ink); border-bottom-color: var(--td-ink); }
.td-controls button.is-active span { color: var(--inverse-text); background: var(--inverse-bg); }
.td-evidence, .td-evidence * { box-sizing: border-box; }
.td-evidence :is(p, span, b, strong, code, small, li, dd) { overflow-wrap: anywhere; }
.td-proof { display: flex; gap: 9px; margin: 0; padding: 16px 20px 18px; color: var(--td-muted); font-size: 16px; line-height: 1.65; }
.td-proof i { flex: 0 0 auto; color: var(--td-ink); font-style: normal; font-weight: 800; }
.td-app, .td-workbench, .td-deploy-console, .td-repo-page, .td-data-console, .td-flow-map, .td-observability, .td-flag-console {
  width: 100%;
  overflow: hidden;
  border: 1px solid var(--td-line);
  border-radius: 12px;
  background: var(--bg);
}
.td-browser-bar {
  display: grid;
  grid-template-columns: 10px 10px 10px minmax(0, 1fr) auto;
  align-items: center;
  gap: 7px;
  min-height: 44px;
  padding: 8px 14px;
  border-bottom: 1px solid var(--td-line);
  background: var(--td-faint);
}
.td-browser-bar > i { width: 9px; height: 9px; border-radius: 50%; background: var(--bg-hover); }
.td-browser-bar code { margin-left: 6px; padding: 5px 10px; border-radius: 6px; color: var(--td-muted); background: var(--bg); font: 14px/1.3 ui-monospace, SFMono-Regular, Menlo, monospace; }
.td-browser-bar b { padding: 4px 8px; border-radius: 5px; color: var(--td-ink); background: var(--bg-hover); font-size: 13px; }
.td-tick { display: flex; align-items: flex-start; gap: 9px; color: var(--td-muted); font-size: 15px; line-height: 1.5; }
.td-tick i { display: grid; place-items: center; flex: 0 0 20px; height: 20px; margin-top: 1px; border-radius: 50%; color: var(--text-2); background: var(--bg-hover); font: 700 13px/1 sans-serif; }
.td-tick.is-pass { color: var(--td-ink); }
.td-tick.is-pass i { color: var(--on-status); background: var(--td-pass); }
.td-tick.is-fail { color: var(--td-alert); font-weight: 700; }
.td-tick.is-fail i { color: var(--on-status); background: var(--td-alert); }

/* 验收标准 */
.td-acceptance-body { display: grid; grid-template-columns: minmax(250px, .72fr) minmax(0, 1.28fr); min-height: 330px; }
.td-criteria-list { display: grid; align-content: start; gap: 22px; padding: 28px; border-right: 1px solid var(--td-line); background: var(--bg-hover); }
.td-criteria-list small { color: var(--td-muted); font: 700 13px/1.3 ui-monospace, monospace; letter-spacing: .08em; }
.td-itinerary { padding: 28px 32px; }
.td-itinerary-title { display: flex; justify-content: space-between; gap: 20px; margin-bottom: 26px; }
.td-itinerary-title span { font-size: 21px; font-weight: 750; }
.td-itinerary-title b { font-size: 18px; }
.td-trip-line { display: grid; grid-template-columns: 48px 16px minmax(0, 1fr); gap: 10px; min-height: 72px; }
.td-trip-line time { color: var(--td-muted); font: 14px/1.4 ui-monospace, monospace; }
.td-trip-line > i { position: relative; width: 10px; height: 10px; margin-top: 4px; border: 2px solid var(--td-ink); border-radius: 50%; }
.td-trip-line:first-of-type > i::after { position: absolute; top: 9px; left: 2px; width: 2px; height: 54px; background: var(--td-line); content: ""; }
.td-trip-line span { display: grid; align-content: start; gap: 4px; }
.td-trip-line b { font-size: 16px; }
.td-trip-line small { color: var(--td-muted); font-size: 14px; }
.td-date-note { display: flex; gap: 9px; padding-top: 16px; border-top: 1px solid var(--td-line); color: var(--td-alert); font-size: 15px; }
.td-date-note b { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; color: var(--on-status); background: var(--td-alert); }
.td-date-note.is-valid { color: var(--td-pass); }
.td-date-note.is-valid b { background: var(--td-pass); }

/* 测试用例 */
.td-login-scene { display: grid; grid-template-columns: minmax(250px, .9fr) minmax(300px, 1.1fr); min-height: 350px; }
.td-login-scene > aside { display: grid; align-content: start; gap: 9px; padding: 32px; background: var(--td-faint); }
.td-login-scene > aside > small { color: var(--td-muted); font: 700 13px/1.3 ui-monospace, monospace; letter-spacing: .08em; }
.td-login-scene > aside > b { margin-top: 8px; font-size: 18px; }
.td-login-scene > aside > span { color: var(--td-muted); font-size: 15px; }
.td-login-scene dl { display: grid; gap: 18px; margin: 24px 0 0; }
.td-login-scene dl div { display: grid; gap: 5px; }
.td-login-scene dt { color: var(--td-muted); font-size: 14px; }
.td-login-scene dd { margin: 0; font-size: 15px; font-weight: 650; }
.td-login-scene form { display: grid; align-content: start; gap: 15px; padding: 32px clamp(28px, 6vw, 72px); }
.td-login-scene h3 { margin: 0 0 8px; font-size: 22px; }
.td-login-scene label { display: grid; gap: 7px; color: var(--td-muted); font-size: 14px; }
.td-login-scene label span { min-height: 44px; padding: 11px 12px; border: 1px solid #bdc2c8; border-radius: 7px; color: var(--td-ink); background: var(--bg); font-size: 15px; }
.td-login-scene button, .td-booking-form button, .td-trip-product button, .td-checkout button, .td-receipt button {
  min-height: 44px;
  border: 0;
  border-radius: 7px;
  color: var(--inverse-text);
  background: var(--inverse-bg);
  font-size: 15px;
  font-weight: 700;
}
.td-form-error { margin: -4px 0 0; color: var(--td-alert); font-size: 14px; line-height: 1.45; }

/* 编辑器、终端与通用工作区 */
.td-workbench > header, .td-data-console > header, .td-flow-map > header, .td-observability > header, .td-flag-console > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 48px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--td-line);
  background: var(--td-faint);
}
.td-workbench > header b, .td-data-console > header b, .td-flow-map > header b, .td-observability > header b { font: 700 15px/1.4 ui-monospace, monospace; }
.td-workbench > header span, .td-data-console > header span, .td-flow-map > header span, .td-observability > header span { color: var(--td-muted); font-size: 14px; }
.td-editor-layout { display: grid; grid-template-columns: 150px minmax(0, 1fr); min-height: 230px; }
.td-editor-layout nav, .td-build-layout nav { display: grid; align-content: start; gap: 8px; padding: 18px 14px; border-right: 1px solid var(--td-line); background: var(--bg-hover); }
.td-editor-layout nav :is(span, b), .td-build-layout nav :is(span, b) { padding: 4px 8px; font: 14px/1.4 ui-monospace, monospace; }
.td-editor-layout nav span { color: var(--td-muted); }
.td-editor-layout nav b { padding-left: 18px; }
.td-editor-layout nav .is-selected { border-radius: 4px; background: var(--bg-hover); }
.td-editor-layout pre, .td-terminal-panel, .td-build-layout pre, .td-double-layout pre, .td-lint-layout pre {
  margin: 0;
  color: #e4e9ef;
  background: #24282d;
  font: 15px/1.75 ui-monospace, SFMono-Regular, Menlo, monospace;
}
.td-editor-layout pre, .td-build-layout pre, .td-double-layout pre, .td-lint-layout pre { padding: 22px; overflow: auto; }
.td-editor-layout em, .td-lint-layout pre em { display: inline-block; width: 28px; color: var(--text-2); font-style: normal; user-select: none; }
.td-editor-layout mark { padding: 1px 3px; color: #fff; background: #4a525d; }
.td-terminal-panel { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px 18px; padding: 14px 18px; border-top: 1px solid #3b4148; }
.td-terminal-panel span { color: #aab3bd; font-size: 14px; }
.td-terminal-panel b { color: #fff; font-size: 14px; }
.td-terminal-panel small { grid-column: 1 / -1; color: #9aa3ad; font-size: 13px; }

/* 集成测试 */
.td-integration-grid { display: grid; grid-template-columns: .8fr 1.2fr; }
.td-integration > header code { color: var(--td-muted); font-size: 14px; }
.td-booking-form { display: grid; align-content: start; gap: 14px; min-height: 270px; padding: 26px; border-right: 1px solid var(--td-line); }
.td-booking-form label { display: grid; gap: 7px; color: var(--td-muted); font-size: 14px; }
.td-booking-form label span { padding: 10px 11px; border: 1px solid var(--td-line); border-radius: 6px; color: var(--td-ink); font-size: 15px; }
.td-network-pane { min-height: 270px; padding: 24px; color: #dfe5ec; background: #24282d; }
.td-network-pane small, .td-record-table small { display: block; margin-bottom: 12px; color: #9fa8b3; font: 700 13px/1.3 ui-monospace, monospace; }
.td-network-pane b { display: inline-block; margin-bottom: 12px; color: #aab3bd; font: 650 14px/1.4 ui-monospace, monospace; }
.td-network-pane b.is-live { color: #8dd4ae; }
.td-network-pane pre { margin: 0; white-space: pre-wrap; font: 14px/1.6 ui-monospace, monospace; }
.td-record-table { grid-column: 1 / -1; padding: 18px 24px 22px; border-top: 1px solid var(--td-line); }
.td-table-head, .td-table-row { display: grid; grid-template-columns: .8fr 1.2fr 1fr; gap: 12px; padding: 9px 12px; font-size: 14px; }
.td-table-head { color: var(--td-muted); background: var(--td-faint); }
.td-table-row { border-bottom: 1px solid var(--td-line); }
.td-table-row.is-new { background: var(--td-pass-soft); }
.td-table-empty { padding: 14px 12px; color: var(--td-muted); font-size: 14px; }

/* E2E */
.td-journey { padding: 22px 28px 28px; }
.td-journey ol { display: grid; grid-template-columns: repeat(3, 1fr); margin: 0 0 28px; padding: 0; list-style: none; }
.td-journey li { position: relative; color: var(--td-muted); font-size: 14px; text-align: center; }
.td-journey li::before { display: block; width: 12px; height: 12px; margin: 0 auto 8px; border-radius: 50%; background: var(--bg-hover); content: ""; }
.td-journey li:not(:last-child)::after { position: absolute; top: 5px; left: calc(50% + 10px); width: calc(100% - 20px); height: 2px; background: var(--bg-hover); content: ""; }
.td-journey li.is-done { color: var(--td-ink); font-weight: 700; }
.td-journey li.is-done::before, .td-journey li.is-done::after { background: var(--td-pass); }
.td-trip-product, .td-confirmation { min-height: 220px; padding: 30px; background: linear-gradient(120deg, #f5f1e9 0 54%, #e1e5df 54%); }
.td-trip-product > span { font-size: 13px; font-weight: 800; letter-spacing: .08em; }
.td-trip-product h3 { max-width: 430px; margin: 12px 0 8px; font-size: 29px; }
.td-trip-product p { color: var(--td-muted); font-size: 15px; }
.td-trip-product button { margin-top: 22px; padding: 0 20px; }
.td-checkout { display: grid; grid-template-columns: 1.3fr .7fr; min-height: 220px; border: 1px solid var(--td-line); }
.td-checkout > div, .td-checkout > aside { display: grid; align-content: start; gap: 14px; padding: 26px; }
.td-checkout > aside { border-left: 1px solid var(--td-line); background: var(--td-faint); }
.td-checkout label { display: grid; gap: 5px; color: var(--td-muted); font-size: 14px; }
.td-checkout label span { padding: 10px; border: 1px solid var(--td-line); border-radius: 6px; color: var(--td-ink); background: var(--bg); }
.td-checkout aside small { color: var(--td-muted); font-size: 13px; }
.td-checkout aside b { font-size: 26px; }
.td-confirmation { display: grid; place-items: center; align-content: center; gap: 6px; text-align: center; background: var(--td-pass-soft); }
.td-confirmation i { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 50%; color: var(--on-status); background: var(--td-pass); font-size: 24px; font-style: normal; }
.td-confirmation span, .td-confirmation p { color: var(--td-muted); font-size: 15px; }
.td-confirmation h3 { margin: 4px 0; font: 800 30px/1.2 ui-monospace, monospace; }

/* 部署类表面 */
.td-deploy-console > header, .td-repo-page > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 18px 20px;
  border-bottom: 1px solid var(--td-line);
  background: var(--td-faint);
}
.td-deploy-console > header div, .td-repo-page > header { min-width: 0; }
.td-deploy-console > header small { display: block; margin-bottom: 5px; color: var(--td-muted); font: 700 12px/1.3 ui-monospace, monospace; letter-spacing: .08em; }
.td-deploy-console > header b { font-size: 18px; }
.td-deploy-console > header strong, .td-repo-page > header em { padding: 6px 9px; border-radius: 5px; color: var(--td-muted); background: var(--bg-hover); font-size: 14px; font-style: normal; }
.td-deploy-console > header strong.is-stop { color: var(--td-alert); background: var(--td-alert-soft); }
.td-deploy-console > header strong.is-go, .td-repo-page > header em.is-open { color: var(--td-pass); background: var(--td-pass-soft); }
.td-live-preview { margin: 20px 20px 0; overflow: hidden; border: 1px solid var(--td-line); border-radius: 8px; }
.td-live-preview main { display: flex; align-items: center; gap: 18px; padding: 18px 20px; }
.td-live-preview main b { margin-right: auto; }
.td-live-preview main span { color: var(--td-muted); font-size: 14px; }
.td-live-preview main button { padding: 8px 13px; border: 0; border-radius: 5px; color: var(--inverse-text); background: var(--inverse-bg); }
.td-probe-log { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; padding: 22px 24px 8px; }

/* 回归 */
.td-receipt { display: grid; grid-template-columns: 1.2fr .8fr; }
.td-receipt main, .td-receipt aside { padding: 28px; }
.td-receipt main { display: grid; gap: 12px; }
.td-receipt main h3 { margin: 0 0 8px; font-size: 21px; }
.td-receipt main > div, .td-receipt main footer { display: flex; justify-content: space-between; gap: 20px; font-size: 15px; }
.td-receipt main > div b { font-weight: 650; }
.td-receipt main .is-change { color: var(--td-alert); text-decoration: underline; text-underline-offset: 4px; }
.td-receipt main .is-pass { color: var(--td-pass); }
.td-receipt main footer { margin-top: 8px; padding-top: 14px; border-top: 1px solid var(--td-line); }
.td-receipt main footer strong { font-size: 21px; }
.td-receipt aside { display: grid; align-content: start; gap: 18px; border-left: 1px solid var(--td-line); background: var(--td-faint); }
.td-receipt aside small { color: var(--td-muted); font: 700 13px/1.4 ui-monospace, monospace; }

/* Build */
.td-build-layout { display: grid; grid-template-columns: 160px minmax(0, 1fr); min-height: 300px; }
.td-build-layout main { display: grid; grid-template-columns: 1.25fr .75fr; background: #24282d; }
.td-build-layout nav span { padding-left: 20px; color: var(--td-muted); }
.td-artifact-tree { position: relative; display: grid; align-content: center; gap: 10px; padding: 24px; color: #9ba5af; border-left: 1px solid #3b4148; font: 14px/1.5 ui-monospace, monospace; }
.td-artifact-tree :is(span, b) { opacity: .34; }
.td-artifact-tree span { padding-left: 18px; }
.td-artifact-tree.is-ready :is(span, b) { color: #e4e9ef; opacity: 1; }
.td-artifact-tree em { justify-self: start; margin-top: 8px; padding: 4px 7px; border-radius: 4px; color: #b8e4c8; background: #294737; font-style: normal; }

/* CI */
.td-repo-page > header { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; }
.td-repo-page > header > span { color: var(--td-muted); font-size: 14px; }
.td-repo-page > header > b { font-size: 17px; }
.td-pr-body { display: grid; grid-template-columns: 1fr 300px; }
.td-pr-body main, .td-pr-body aside { padding: 26px; }
.td-pr-body main { display: grid; gap: 15px; }
.td-pr-body main > small { color: var(--td-muted); font-size: 14px; }
.td-pr-body h3 { margin: 3px 0 5px; font-size: 19px; }
.td-pr-body .td-tick { justify-content: space-between; padding: 10px 0; border-bottom: 1px solid #eceef0; }
.td-pr-body .td-tick i { margin-right: 2px; }
.td-pr-body .td-tick code { margin-left: auto; color: var(--td-muted); font-size: 13px; }
.td-pr-body aside { display: grid; align-content: center; gap: 12px; border-left: 1px solid var(--td-line); background: var(--td-faint); }
.td-pr-body aside button { min-height: 45px; border: 0; border-radius: 7px; color: var(--text-2); background: var(--bg-hover); font-weight: 750; }
.td-pr-body aside button.is-enabled { color: var(--on-status); background: var(--td-pass); }
.td-pr-body aside span { color: var(--td-muted); font-size: 14px; line-height: 1.5; text-align: center; }

/* CD */
.td-job-list { display: grid; padding: 8px 22px; }
.td-job-list > div { display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; align-items: center; gap: 12px; min-height: 68px; border-bottom: 1px solid #eceef0; }
.td-job-list > div > i { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; color: var(--td-muted); background: var(--bg-hover); font-size: 13px; font-style: normal; }
.td-job-list > div:first-child > i, .td-job-list > div.is-current > i { color: var(--on-status); background: var(--td-pass); }
.td-job-list > div.is-waiting > i { color: var(--td-ink); background: var(--bg-hover); }
.td-job-list span { display: grid; gap: 3px; }
.td-job-list span b { font-size: 15px; }
.td-job-list span small { color: var(--td-muted); font-size: 13px; }
.td-job-list button { padding: 8px 12px; border: 0; border-radius: 6px; color: var(--inverse-text); background: var(--inverse-bg); font-weight: 700; }
.td-cd-key { display: grid; grid-template-columns: 140px minmax(0, 1fr); gap: 20px; padding: 18px 22px; background: var(--td-faint); }
.td-cd-key b { font-size: 17px; }
.td-cd-key span { color: var(--td-muted); font-size: 15px; line-height: 1.55; }

/* 环境 */
.td-env-banner { padding: 9px 16px; color: var(--text-2); background: var(--bg-hover); font-size: 14px; text-align: center; }
.td-env-0 .td-env-banner { color: var(--td-muted); background: var(--bg-hover); }
.td-env-2 .td-env-banner { color: var(--inverse-text); background: var(--inverse-bg); }
.td-staging main { padding: 0 28px 30px; }
.td-staging main > header { display: flex; align-items: center; gap: 24px; min-height: 64px; border-bottom: 1px solid var(--td-line); }
.td-staging main > header b { margin-right: auto; }
.td-staging main > header span, .td-staging main > header i { color: var(--td-muted); font-size: 14px; font-style: normal; }
.td-staging article { max-width: 560px; margin-top: 26px; padding: 26px; background: var(--bg-hover); }
.td-staging article small { color: var(--td-muted); font-size: 13px; }
.td-staging article h3 { margin: 9px 0 7px; font-size: 24px; }
.td-staging article p { color: var(--td-muted); font-size: 15px; }
.td-staging article button { margin-top: 12px; padding: 9px 14px; border: 0; border-radius: 5px; color: var(--inverse-text); background: var(--inverse-bg); }

/* 覆盖率路径树 */
.td-tree { display: grid; justify-items: center; padding: 30px 30px 20px; }
.td-tree-node, .td-tree-branches :is(b, strong) { min-width: 180px; padding: 11px 14px; border-radius: 6px; background: var(--bg-hover); font-size: 15px; text-align: center; }
.td-tree-node.is-covered, .td-tree-branches .is-covered { color: var(--td-pass); background: var(--td-pass-soft); }
.td-tree-split { position: relative; width: 50%; height: 40px; border-bottom: 1px solid #aeb4bb; }
.td-tree-split::before { position: absolute; top: 0; left: 50%; width: 1px; height: 100%; background: #aeb4bb; content: ""; }
.td-tree-branches { display: grid; grid-template-columns: repeat(2, minmax(210px, 1fr)); gap: 80px; }
.td-tree-branches section { position: relative; display: grid; justify-items: center; gap: 0; }
.td-tree-branches section::before { width: 1px; height: 18px; background: #aeb4bb; content: ""; }
.td-tree-branches i { width: 1px; height: 24px; background: #aeb4bb; }
.td-tree-branches .is-missed { color: var(--td-muted); background: repeating-linear-gradient(135deg, #f0f1f2 0 7px, #e5e7e9 7px 8px); }
.td-tree-branches em { margin-top: 9px; color: var(--td-alert); font-size: 14px; font-style: normal; }

/* 测试替身 */
.td-double-layout { display: grid; grid-template-columns: .9fr 1.1fr; min-height: 240px; }
.td-request-inspector { padding: 24px; }
.td-request-inspector small { font: 700 13px/1.4 ui-monospace, monospace; }
.td-request-inspector dl { display: grid; margin: 18px 0 0; }
.td-request-inspector dl div { display: grid; grid-template-columns: 90px minmax(0, 1fr); gap: 12px; padding: 10px 0; border-bottom: 1px solid #eceef0; font-size: 14px; }
.td-request-inspector dt { color: var(--td-muted); }
.td-request-inspector dd { margin: 0; font-family: ui-monospace, monospace; }
.td-request-inspector dd.is-fixed { color: var(--td-pass); font-weight: 700; }
.td-repeat-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--td-line); border-top: 1px solid var(--td-line); }
.td-repeat-row span { padding: 13px; color: var(--td-muted); background: var(--td-faint); font-size: 14px; text-align: center; }

/* Fixture */
.td-data-console > header div { display: flex; gap: 10px; }
.td-data-console > header code { color: var(--td-muted); font-size: 14px; }
.td-db-table { margin: 24px; overflow: hidden; border: 1px solid var(--td-line); border-radius: 7px; }
.td-db-head, .td-db-row { display: grid; grid-template-columns: .8fr 1.5fr .8fr .7fr; gap: 12px; padding: 11px 14px; font-size: 14px; }
.td-db-head { color: var(--td-muted); background: var(--td-faint); }
.td-db-row.is-created { background: var(--td-pass-soft); }
.td-db-row.is-used { background: var(--bg-hover); }
.td-db-row em { color: var(--td-muted); font-style: normal; }
.td-db-empty { padding: 28px; color: var(--td-muted); font-size: 15px; text-align: center; }
.td-fixture ol { display: grid; grid-template-columns: repeat(3, 1fr); margin: 0; padding: 0 24px 10px; list-style: none; counter-reset: steps; }
.td-fixture li { display: grid; grid-template-columns: 24px minmax(0, 1fr); align-items: center; gap: 8px; color: var(--td-muted); font-size: 14px; counter-increment: steps; }
.td-fixture li::before { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; background: var(--bg-hover); content: counter(steps); }
.td-fixture li.is-current, .td-fixture li.is-done { color: var(--td-ink); font-weight: 700; }
.td-fixture li.is-current::before, .td-fixture li.is-done::before { color: var(--on-status); background: var(--td-pass); }

/* Flaky */
.td-run-table { padding: 16px 22px 8px; }
.td-run-table > div { display: grid; grid-template-columns: repeat(4, 1fr); padding: 10px 12px; border-bottom: 1px solid #eceef0; font: 14px/1.4 ui-monospace, monospace; }
.td-run-table > div:first-child { color: var(--td-muted); background: var(--td-faint); }
.td-run-table > div.is-failed { color: var(--td-alert); background: var(--td-alert-soft); }
.td-trace-clue { display: grid; grid-template-columns: 130px minmax(0, 1fr); gap: 16px; margin: 12px 22px 0; padding: 14px; background: var(--td-faint); }
.td-trace-clue b { font-size: 14px; }
.td-trace-clue span { color: var(--td-muted); font-size: 14px; line-height: 1.5; }

/* Lint */
.td-lint-layout { display: grid; grid-template-columns: 1.35fr .65fr; min-height: 260px; }
.td-lint-layout pre em.is-error { color: var(--on-status); background: var(--td-alert); }
.td-lint-layout aside { padding: 22px; background: var(--bg-hover); }
.td-lint-layout aside > small { display: block; margin-bottom: 18px; color: var(--td-muted); font: 700 13px/1.3 ui-monospace, monospace; }
.td-lint-layout aside > span { color: var(--td-muted); font-size: 14px; }
.td-lint-layout aside div { display: grid; gap: 6px; padding: 12px; background: var(--td-alert-soft); }
.td-lint-layout aside div b, .td-lint-layout aside div span, .td-lint-layout aside div code { color: var(--td-alert); font-size: 14px; }
.td-lint-layout aside b.is-clear { color: var(--td-pass); font-size: 15px; }

/* 监控 */
.td-observability > header div small { display: block; margin-bottom: 4px; color: var(--td-muted); font-size: 13px; }
.td-metric-summary { display: flex; align-items: baseline; gap: 12px; padding: 20px 24px 0; }
.td-metric-summary b { font-size: 34px; }
.td-metric-summary b.is-alert { color: var(--td-alert); }
.td-metric-summary span { color: var(--td-muted); font-size: 14px; }
.td-metric-summary em { margin-left: auto; color: var(--td-pass); font-size: 14px; font-style: normal; font-weight: 700; }
.td-metric-summary b.is-alert ~ em { color: var(--td-alert); }
.td-metric-chart { position: relative; display: flex; align-items: flex-end; gap: 12px; height: 190px; margin: 0 24px; padding: 34px 10px 28px; border-bottom: 1px solid var(--td-line); }
.td-metric-chart > i { flex: 1; height: 22%; background: #707984; }
.td-metric-chart > i:nth-of-type(2) { height: 26%; }.td-metric-chart > i:nth-of-type(3) { height: 20%; }
.td-metric-chart > i.is-high { height: 72%; background: var(--td-alert); }
.td-threshold { position: absolute; right: 0; left: 0; bottom: 62px; border-top: 1px dashed var(--td-alert); color: var(--td-alert); font-size: 12px; text-align: right; }
.td-metric-chart > b { position: absolute; right: 18%; bottom: 28px; padding: 4px 7px; color: var(--inverse-text); background: var(--inverse-bg); font-size: 12px; }
.td-alert-row { display: grid; grid-template-columns: 24px minmax(0, 1fr) auto; align-items: center; gap: 10px; margin: 18px 24px 0; padding: 13px 14px; background: var(--td-pass-soft); font-size: 14px; }
.td-alert-row i { color: var(--td-pass); font-style: normal; font-weight: 800; }
.td-alert-row.is-active { color: var(--td-alert); background: var(--td-alert-soft); }
.td-alert-row.is-active i { color: var(--td-alert); }

/* 回滚 */
.td-release-history { padding: 10px 22px; }
.td-release-history > div { display: grid; grid-template-columns: 120px minmax(0, 1fr) auto; align-items: center; gap: 16px; min-height: 64px; border-bottom: 1px solid #eceef0; }
.td-release-history i { font: 700 15px/1.4 ui-monospace, monospace; }
.td-release-history span { color: var(--td-muted); font-size: 14px; }
.td-release-history b { color: var(--td-muted); font-size: 14px; }
.td-release-history .is-serving { background: var(--td-pass-soft); }
.td-release-history .is-serving b { color: var(--td-pass); }
.td-release-history .is-serving.is-bad { background: var(--td-alert-soft); }
.td-release-history .is-serving.is-bad b, .td-release-history .is-serving.is-bad i { color: var(--td-alert); }
.td-health-strip { display: grid; grid-template-columns: 80px minmax(0, 1fr) 60px; align-items: center; gap: 16px; padding: 18px 22px; background: var(--td-faint); }
.td-health-strip > span { color: var(--td-muted); font-size: 14px; }
.td-health-strip > div { display: flex; align-items: flex-end; gap: 7px; height: 40px; }
.td-health-strip i { flex: 1; height: 35%; background: #b8bec5; }
.td-health-strip i.is-bad { height: 95%; background: var(--td-alert); }
.td-health-strip i.is-mid { height: 58%; background: #8e959e; }
.td-health-strip i.is-good { height: 18%; background: var(--td-pass); }

/* 功能开关 */
.td-flag-console > header button { display: flex; align-items: center; gap: 7px; padding: 7px 10px; border: 0; border-radius: 99px; color: var(--on-status); background: var(--td-pass); font-weight: 800; }
.td-flag-console > header button i { position: relative; order: 2; width: 28px; height: 16px; border-radius: 99px; background: rgba(255,255,255,.35); }
.td-flag-console > header button i::after { position: absolute; top: 2px; right: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--bg); content: ""; }
.td-flag-console > header button.is-off { color: var(--td-muted); background: var(--bg-hover); }
.td-flag-console > header button.is-off i::after { right: auto; left: 2px; }
.td-flag-console > header small { display: block; margin-bottom: 3px; color: var(--td-muted); font: 13px/1.4 ui-monospace, monospace; }
.td-flag-grid { display: grid; grid-template-columns: 240px minmax(0, 1fr); }
.td-flag-grid > aside { padding: 22px; background: var(--td-faint); }
.td-flag-grid > aside > div { display: grid; gap: 4px; padding: 12px 0; border-bottom: 1px solid var(--td-line); }
.td-flag-grid > aside span { color: var(--td-muted); font-size: 13px; }
.td-flag-grid > aside b { font-size: 15px; }
.td-flag-grid > main { display: grid; grid-template-columns: repeat(2, 1fr); gap: 18px; padding: 22px; }
.td-flag-grid section { min-width: 0; }
.td-flag-grid section > small { display: block; min-height: 36px; color: var(--td-muted); font-size: 13px; line-height: 1.4; }
.td-old-trip, .td-new-trip { display: grid; align-content: center; gap: 7px; min-height: 140px; padding: 20px; background: var(--bg-hover); }
.td-new-trip { color: #fff; background: #303840; }
.td-old-trip b, .td-new-trip b { font-size: 17px; }
.td-old-trip span, .td-new-trip span { color: inherit; font-size: 14px; opacity: .72; }

/* 金丝雀发布 */
.td-canary-routing { padding: 24px; background: var(--td-faint); }
.td-traffic-source { display: flex; align-items: baseline; justify-content: space-between; gap: 20px; margin-bottom: 18px; padding-bottom: 14px; border-bottom: 1px solid var(--td-line); }
.td-traffic-source span { color: var(--td-muted); font-size: 15px; }
.td-traffic-source b { font-size: 20px; }
.td-version-lanes { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; }
.td-version-lanes section { min-width: 0; padding: 20px; background: var(--bg); }
.td-version-lanes section > header { display: flex; align-items: center; justify-content: space-between; gap: 18px; }
.td-version-lanes section > header span { display: grid; gap: 4px; }
.td-version-lanes section > header small { color: var(--td-muted); font: 700 12px/1.3 ui-monospace, monospace; letter-spacing: .08em; }
.td-version-lanes section > header b { font: 750 17px/1.3 ui-monospace, monospace; }
.td-version-lanes section > header strong { font-size: 24px; }
.td-traffic-meter { height: 10px; margin: 18px 0; overflow: hidden; background: var(--bg-hover); }
.td-traffic-meter i { display: block; height: 100%; background: var(--inverse-bg); transition: width .2s ease; }
.td-version-lanes .is-canary .td-traffic-meter i { min-width: 0; background: #7f8994; }
.td-version-lanes .is-failed .td-traffic-meter i { background: var(--td-alert); }
.td-version-lanes section > p { display: flex; justify-content: space-between; gap: 16px; margin: 0; color: var(--td-muted); font-size: 14px; }
.td-version-lanes .is-failed > p b { color: var(--td-alert); }

/* 蓝绿部署 */
.td-environment-routing { padding: 22px 24px 24px; background: var(--td-faint); }
.td-route-shares { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; margin-bottom: 8px; color: #9aa1aa; font: 700 15px/1.4 ui-monospace, monospace; text-align: center; }
.td-route-shares span { min-height: 28px; }
.td-route-shares span.is-active { color: var(--td-ink); }
.td-environment-pools { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; }
.td-environment-pools > section { min-width: 0; overflow: hidden; background: var(--bg); opacity: .74; }
.td-environment-pools > section.is-live { opacity: 1; box-shadow: 0 0 0 2px var(--td-ink); }
.td-environment-pools > section > header { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 12px 16px; color: var(--on-status); background: var(--td-blue); }
.td-environment-pools > section.is-green > header { background: var(--td-pass); }
.td-environment-pools > section > header span { font: 800 13px/1.3 ui-monospace, monospace; letter-spacing: .08em; }
.td-environment-pools > section > header b { font: 750 15px/1.3 ui-monospace, monospace; }
.td-travel-screen { display: grid; align-content: center; gap: 8px; min-height: 132px; padding: 22px; background: var(--bg); }
.td-travel-screen b { font-size: 18px; }
.td-travel-screen span { color: var(--td-muted); font-size: 14px; line-height: 1.5; }
.td-environment-pools > section > p { margin: 0; padding: 11px 16px; color: var(--td-muted); background: var(--bg-hover); font-size: 14px; font-weight: 700; }
.td-environment-pools > section.is-green > p { background: var(--td-pass-soft); }

/* 列表缩略图：每个词使用业务对象，不显示“术语 + 1/2/3”。 */
.testing-delivery-preview {
  width: min(100%, 410px);
  min-height: 154px;
  margin: auto;
  padding: 0;
  color: var(--td-ink, #20242a);
  background: transparent;
  font-family: ui-sans-serif, system-ui, sans-serif;
}
.testing-delivery-preview > strong { display: none; }
.testing-delivery-preview :is(header, p, h4, ol, dl) { margin: 0; }
.testing-delivery-preview :is(small, span, em, code, b, strong, button, dt, dd, p, li) { font-size: 13px; line-height: 1.35; }
.testing-delivery-preview button { pointer-events: none; }
