@media (max-width: 720px) {
  .detail-hero .dh-demo.style-detail-demo:has(.style-brutalism-demo) { aspect-ratio: 3 / 4; }
  .style-brutalism-demo { padding: 10px; }
  .style-brutalism-app { box-shadow: 5px 5px 0 #050505; }
  .style-brutalism-brand > i, .style-brutalism-live { display: none; }
  .style-brutalism-shell { grid-template-columns: 1fr; }
  .style-brutalism-sidebar { display: none; }
  .style-brutalism-main { padding: 10px; }
  .style-brutalism-hero { min-height: 60px; }
  .style-brutalism-lower { grid-template-columns: minmax(0, 1.5fr) minmax(120px, .7fr); }
