@media (max-width: 500px) {
  .style-brutalism-topbar { height: 36px; }
  .style-brutalism-profile > b { display: none; }
  .style-brutalism-main { gap: 7px; padding: 8px; }
  .style-brutalism-hero { min-height: 54px; }
  .style-brutalism-hero h2 { font-size: 18px; }
