/* Apple photo studio: sourced wallpaper first, chrome second. */
.apple-thumb { display: grid; grid-template-rows: 38px minmax(0, 1fr); background: #e9e9ee; }
.apple-thumb > div { display: flex; align-items: center; gap: 8px; padding: 0 14px; background: rgba(255, 255, 255, .88); border-bottom: 1px solid rgba(0, 0, 0, .07); color: #1d1d1f; font-size: 11px; }
.apple-thumb > div > i { font-size: 15px; }
.apple-thumb > div > span { font-weight: 650; }
.apple-thumb > div > b { margin-left: auto; color: #86868b; font-size: 11px; font-weight: 500; }
.apple-thumb > section { position: relative; min-height: 0; padding: 12px; overflow: hidden; }
.apple-thumb > section > img { width: 100%; height: 100%; object-fit: cover; display: block; border-radius: 11px; box-shadow: 0 16px 34px rgba(39, 32, 53, .18); }
.apple-thumb > section > aside { position: absolute; z-index: 1; top: 24px; right: 24px; bottom: 24px; width: 31%; display: flex; flex-direction: column; gap: 7px; padding: 11px; border: 1px solid rgba(255, 255, 255, .7); border-radius: 12px; background: rgba(250, 250, 252, .68); backdrop-filter: blur(18px) saturate(130%); -webkit-backdrop-filter: blur(18px) saturate(130%); box-shadow: 0 12px 30px rgba(50, 39, 65, .16); color: #343438; }
.apple-thumb > section > aside small { font-size: 11px; letter-spacing: 1.2px; color: #7b7b82; }
.apple-thumb > section > aside b { font-size: 11px; font-weight: 550; }
