/* domains/design/classic-styles.css */
/* classic styles module：设计史经典风格（style-skeuomorphism / style-flat / style-material / style-neumorphism） */

/* ============ 拟物化 Skeuomorphism ============ */
/* 亚麻布纹底（可复用） */
.style-skeuomorphism-linen {
  background-color: #c9ccd4;
  background-image:
    repeating-linear-gradient(0deg, rgba(255,255,255,.06) 0 1px, transparent 1px 3px),
    repeating-linear-gradient(90deg, rgba(0,0,0,.05) 0 1px, transparent 1px 3px);
}
/* 卡片 demo：亚麻底 + 备忘录 + 拟物控件 */
.style-skeuomorphism-demo {
  display: flex; gap: 12px; width: 100%; max-width: 640px; height: 204px;
  border-radius: 12px; padding: 12px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.5), inset 0 0 32px rgba(0,0,0,.1);
}
.style-skeuomorphism-notes {
  flex: 1.45; min-width: 0; border-radius: 4px; overflow: hidden;
  display: flex; flex-direction: column;
  box-shadow: 0 4px 10px rgba(0,0,0,.35), 0 1px 0 rgba(255,255,255,.4);
}
/* 皮革缝线标题栏 */
.style-skeuomorphism-bar {
  background: linear-gradient(#96684a 0%, #7a4f31 50%, #6a4126 100%);
  border-top: 1px dashed rgba(255,230,200,.55);
  border-bottom: 1px dashed rgba(255,230,200,.55);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.2), inset 0 -3px 5px rgba(0,0,0,.3);
  color: #f7e8d2; text-shadow: 0 -1px 1px rgba(0,0,0,.55);
  font-size: 13px; font-weight: 700; text-align: center; padding: 7px 0; letter-spacing: 2px;
}
/* 黄纸：横纹 + 左侧红线 */
.style-skeuomorphism-paper {
  flex: 1; position: relative;
  background: repeating-linear-gradient(#fbf2c4 0 21px, #dcc57f 21px 22px);
  padding: 6px 12px 6px 30px;
  font-family: "Marker Felt", "Bradley Hand", "Comic Sans MS", cursive;
  font-size: 12px; line-height: 22px; color: #6b5335;
}
.style-skeuomorphism-paper::before {
  content: ""; position: absolute; top: 0; bottom: 0; left: 20px;
  width: 2px; background: rgba(214,69,65,.55);
}
.style-skeuomorphism-side {
  flex: 1; min-width: 0; display: flex; flex-direction: column;
  gap: 12px; align-items: center; justify-content: center;
}
/* iOS 6 滑动开关 */
.style-skeuomorphism-switch {
  position: relative; flex: none; width: 80px; height: 30px; border-radius: 15px;
  background: linear-gradient(#f7f7f7, #e2e2e6);
  box-shadow: inset 0 2px 5px rgba(0,0,0,.3), 0 1px 0 rgba(255,255,255,.7);
}
.style-skeuomorphism-switch-fill {
  position: absolute; left: 0; top: 0; bottom: 0; width: 58%;
  border-radius: 15px 0 0 15px;
  background: linear-gradient(#5ab0fb, #1e6fd4);
  box-shadow: inset 0 2px 4px rgba(0,0,0,.25);
}
.style-skeuomorphism-switch-fill::after {
  content: "ON"; position: absolute; left: 9px; top: 50%; transform: translateY(-50%);
  color: #fff; font-size: 12px; font-weight: 700; font-style: normal;
  text-shadow: 0 -1px 1px rgba(0,0,0,.4);
}
.style-skeuomorphism-switch-knob {
  position: absolute; right: 2px; top: 2px; width: 26px; height: 26px; border-radius: 50%;
  background: linear-gradient(#ffffff, #d6d9e0);
  box-shadow: 0 2px 4px rgba(0,0,0,.45), inset 0 1px 0 #fff;
}
.style-skeuomorphism-switch.sm { width: 58px; height: 22px; }
.style-skeuomorphism-switch.sm .style-skeuomorphism-switch-knob { width: 18px; height: 18px; }
/* iOS 6 玻璃按钮 */
.style-skeuomorphism-btn {
  display: inline-block; padding: 7px 24px; border-radius: 8px;
  background: linear-gradient(#7ec0f8 0%, #2a7de1 50%, #1b62c4 51%, #2f7ce0 100%);
  border: 1px solid #144e9e; color: #fff;
  font-size: 13px; font-weight: 600; text-shadow: 0 -1px 1px rgba(0,0,0,.45);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.55), 0 2px 5px rgba(0,0,0,.35);
}
/* 拟物小按钮（示意图用，灰色玻璃） */
.style-skeuomorphism-mini-btn {
  display: inline-block; padding: 4px 14px; border-radius: 7px;
  background: linear-gradient(#fefefe, #dfe2e8);
  border: 1px solid #a8adb6; color: #3b3f46;
  font-size: 12px; font-weight: 600; text-shadow: 0 1px 0 #fff;
  box-shadow: inset 0 1px 0 #fff, 0 2px 4px rgba(0,0,0,.28);
}
/* 材质小样 */
.style-skeuomorphism-mini-swatch {
  display: inline-flex; align-items: center; justify-content: center;
  width: 52px; height: 34px; border-radius: 4px; flex: none;
  font-size: 12px; color: #fff; text-shadow: 0 -1px 1px rgba(0,0,0,.5);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.25), 0 2px 4px rgba(0,0,0,.3);
}
.style-skeuomorphism-mini-swatch.leather {
  background: linear-gradient(#96684a, #6a4126);
  border-top: 1px dashed rgba(255,230,200,.6); border-bottom: 1px dashed rgba(255,230,200,.6);
}
.style-skeuomorphism-mini-swatch.linen {
  background-color: #c9ccd4; color: #5a5f6b; text-shadow: 0 1px 0 rgba(255,255,255,.6);
  background-image:
    repeating-linear-gradient(0deg, rgba(255,255,255,.1) 0 1px, transparent 1px 3px),
    repeating-linear-gradient(90deg, rgba(0,0,0,.08) 0 1px, transparent 1px 3px);
}
.style-skeuomorphism-mini-swatch.metal {
  background: repeating-linear-gradient(90deg, #c2c8d2 0 2px, #e2e6ee 2px 4px);
  color: #4a5058; text-shadow: 0 1px 0 #fff;
}
.style-skeuomorphism-mini-swatch.wood {
  background: repeating-linear-gradient(90deg, #a06a3f 0 6px, #8a5930 6px 12px);
}
/* 皮革小条（示意图用） */
.style-skeuomorphism-mini-strip {
  display: block; width: 100%; height: 14px; border-radius: 3px;
  background: linear-gradient(#96684a, #6a4126);
  border-top: 1px dashed rgba(255,230,200,.6); border-bottom: 1px dashed rgba(255,230,200,.6);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.2), 0 2px 4px rgba(0,0,0,.25);
}
/* 计算器按键 */
.style-skeuomorphism-keys { display: flex; gap: 6px; }
.style-skeuomorphism-key {
  width: 26px; height: 26px; border-radius: 6px;
  background: linear-gradient(#58585c, #323236);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.25), 0 2px 3px rgba(0,0,0,.4);
  color: #fff; font-size: 12px; display: flex; align-items: center; justify-content: center;
}
.style-skeuomorphism-key.orange { background: linear-gradient(#ffb04d, #f57c00); }
/* anatomy */
.style-skeuomorphism-anat { display: flex; gap: 14px; align-items: center; flex-wrap: wrap; width: 100%; }
.style-skeuomorphism-anat-notes {
  width: 172px; border-radius: 4px; overflow: hidden;
  box-shadow: 0 3px 8px rgba(0,0,0,.3); display: flex; flex-direction: column;
}
.style-skeuomorphism-anat-paper { display: block; min-height: 44px; }
.style-skeuomorphism-shadowchip {
  display: inline-flex; align-items: center; justify-content: center;
  width: 76px; height: 34px; border-radius: 4px; background: #fff;
  font-size: 12px; color: var(--text-2);
  box-shadow: 0 8px 16px rgba(0,0,0,.3), 0 2px 4px rgba(0,0,0,.2);
}

/* ============ 扁平化 Flat Design ============ */
.style-flat-demo { display: flex; gap: 10px; width: 100%; max-width: 640px; height: 204px; }
/* Metro 磁贴墙 */
.style-flat-tiles {
  flex: 1.6; min-width: 0;
  display: grid; grid-template-columns: repeat(4, 1fr); grid-template-rows: repeat(2, 1fr); gap: 6px;
}
.style-flat-tile {
  color: #fff; font-size: 12px; padding: 7px 8px; min-width: 0;
  display: flex; flex-direction: column; justify-content: space-between;
}
.style-flat-tile i { font-size: 18px; font-style: normal; }
.style-flat-tile.wide { grid-column: span 2; }
.style-flat-tile.c-blue { background: #1ba1e2; }
.style-flat-tile.c-green { background: #60a917; }
.style-flat-tile.c-orange { background: #fa6800; }
.style-flat-tile.c-purple { background: #aa00ff; }
.style-flat-tile.c-teal { background: #00aba9; }
.style-flat-tile.c-red { background: #e51400; }
/* 右栏：iOS 7 天气 + 图标排 */
.style-flat-side { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 8px; }
.style-flat-weather {
  flex: 1; background: #2d89ef; color: #fff; padding: 10px 14px;
  display: flex; flex-direction: column; justify-content: center;
}
.style-flat-weather b { font-size: 46px; font-weight: 200; line-height: 1; }
.style-flat-weather span { font-size: 12px; opacity: .9; }
.style-flat-icons { display: flex; gap: 8px; align-items: center; }
.style-flat-icon { width: 34px; height: 34px; border-radius: 8px; flex: none; }
/* 示意图小件 */
.style-flat-mini-tile {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 44px; height: 30px; padding: 0 10px;
  background: #1ba1e2; color: #fff; font-size: 12px;
}
.style-flat-mini-btn {
  display: inline-block; background: #2d89ef; color: #fff;
  font-size: 12px; padding: 5px 16px; border-radius: 4px;
}
.style-flat-mini-ico {
  display: inline-flex; align-items: center; justify-content: center;
  width: 30px; height: 30px; border-radius: 7px; flex: none;
  color: #fff; font-size: 14px; font-style: normal;
}
/* anatomy */
.style-flat-anat { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; width: 100%; }
.style-flat-anat-chip {
  display: inline-flex; align-items: center; justify-content: center;
  height: 34px; padding: 0 12px; background: #f2f3f5; color: #3b3f46; font-size: 12px;
}
.style-flat-anat-radius { border-radius: 0; }
.style-flat-anat-type { font-size: 18px; font-weight: 200; color: var(--text); letter-spacing: 1px; }

/* ============ Material Design ============ */
.style-material-demo {
  position: relative; width: 100%; max-width: 560px; height: 208px;
  background: #fafafa; border-radius: 4px; overflow: hidden;
  box-shadow: 0 3px 10px rgba(0,0,0,.22);
