/* domains/design/expressive-styles.css */
/* expressive styles module:个性风格(Y2K 千禧 / 孟菲斯 / 终端极客 / 日式侘寂) */


/* ==================== Y2K 千禧 ==================== */
.style-y2k-demo {
  position: relative; overflow: hidden; border-radius: 10px;
  min-height: 196px; padding: 22px;
  display: flex; align-items: center; justify-content: center;
  background: linear-gradient(155deg, #bfe3ff 0%, #e3f2ff 38%, #ffd9ef 78%, #ffc2e4 100%);
}
/* 彩虹渐变光斑 */
.style-y2k-blob {
  position: absolute; border-radius: 50%; filter: blur(2px); opacity: .8;
  background: conic-gradient(from 210deg, #a8e6ff, #ffd1ec, #fff3b0, #c3f5e8, #a8e6ff);
}
.style-y2k-star {
  position: absolute; color: #fff; font-style: normal;
  text-shadow: 0 0 8px rgba(255,158,214,.95), 0 1px 2px rgba(150,110,200,.55);
}
/* 金属渐变文字 */
.style-y2k-chrome {
  display: inline-block;
  font-size: 32px; font-weight: 800; font-style: italic; letter-spacing: 1px;
  background: linear-gradient(180deg, #feffff 0%, #c7d3e3 28%, #67768c 47%, #eef4fb 53%, #93a5bc 74%, #f7fbff 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 2px 0 rgba(255,255,255,.95)) drop-shadow(0 4px 8px rgba(105,90,160,.4));
}
.style-y2k-bubble {
  display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: 1px;
  color: #fff; padding: 8px 18px; border-radius: 999px;
  border: 1px solid rgba(255,255,255,.75);
  background: linear-gradient(180deg, #ffc9e5 0%, #ff8fc7 46%, #f556a8 100%);
  box-shadow: inset 0 2px 2px rgba(255,255,255,.9), inset 0 -3px 5px rgba(190,20,110,.4), 0 5px 12px rgba(245,86,168,.45);
}
.style-y2k-bubble.blue {
  background: linear-gradient(180deg, #c9ecff 0%, #7ec8f5 46%, #3d9fe8 100%);
  box-shadow: inset 0 2px 2px rgba(255,255,255,.9), inset 0 -3px 5px rgba(20,90,170,.4), 0 5px 12px rgba(61,159,232,.45);
}
/* 配方拆解 */
.style-y2k-anat { display: inline-flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.style-y2k-sw {
  display: inline-flex; align-items: center; justify-content: center;
  width: 74px; height: 44px; border-radius: 6px; border: 1px solid var(--border-light);
  font-size: 12px; color: var(--text-2); overflow: hidden;
}
.style-y2k-anat-plus { font-size: 13px; color: var(--text-3); }

/* ==================== 孟菲斯 Memphis ==================== */
.style-memphis-demo {
  position: relative; overflow: hidden; border-radius: 10px;
  min-height: 196px; padding: 22px;
  display: flex; align-items: center; justify-content: center;
  background: #fff8ef;
}
.style-memphis-dots {
  position: absolute; width: 54px; height: 54px; border-radius: 50%;
  background: #ffd23f; border: 3px solid #111;
  background-image: radial-gradient(#111 1.6px, transparent 1.8px); background-size: 10px 10px;
}
.style-memphis-tri {
  position: absolute; width: 0; height: 0;
  border-left: 16px solid transparent; border-right: 16px solid transparent;
  border-bottom: 28px solid #3d5af1;
}
.style-memphis-squiggle {
  position: absolute; width: 74px; height: 16px;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='74' height='16'><path d='M3 8 Q 11 1, 19 8 T 35 8 T 51 8 T 67 8' fill='none' stroke='%23ee4266' stroke-width='4' stroke-linecap='round'/></svg>") center/contain no-repeat;
}
.style-memphis-ring {
  position: absolute; width: 32px; height: 32px; border-radius: 50%;
  border: 6px solid #22c1a3;
}
.style-memphis-plus { position: absolute; font-size: 22px; font-weight: 800; color: #111; font-style: normal; }
.style-memphis-btn {
  display: inline-block; font-size: 12px; font-weight: 800; letter-spacing: 1px;
  color: #111; background: #ffd23f; padding: 8px 18px;
  border: 3px solid #111; border-radius: 0; box-shadow: 4px 4px 0 #111;
}
/* 配方拆解 */
.style-memphis-anat { display: inline-flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.style-memphis-sw {
  display: inline-flex; align-items: center; justify-content: center;
  width: 74px; height: 44px; border-radius: 6px; border: 1px solid var(--border-light);
  font-size: 12px; color: var(--text-2); overflow: hidden; background: #fff;
}
.style-memphis-anat-plus { font-size: 13px; color: var(--text-3); }

/* ==================== 终端极客 Terminal Aesthetic ==================== */
.style-terminal-demo {
  position: relative; overflow: hidden; border-radius: 10px;
  min-height: 196px; padding: 18px 22px;
  background: #0b0d0b; color: #d7ddd7;
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
}
.style-terminal-demo .style-terminal-g { color: #4af626; }
.style-terminal-demo .style-terminal-d { color: #6b7a6b; }
.style-terminal-cursor {
  display: inline-block; width: 9px; height: 16px; margin-left: 3px;
  background: #4af626; vertical-align: -3px;
  animation: style-terminal-blink 1.06s steps(1) infinite;
}
@keyframes style-terminal-blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
/* 配方拆解 */
.style-terminal-anat { display: inline-flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.style-terminal-sw {
  display: inline-flex; align-items: center; justify-content: center;
  width: 88px; height: 44px; border-radius: 6px; border: 1px solid var(--border-light);
  font-size: 12px; color: var(--text-2); overflow: hidden; background: #0b0d0b;
  font-family: ui-monospace, Menlo, monospace;
}
.style-terminal-anat-plus { font-size: 13px; color: var(--text-3); }

/* ==================== 日式侘寂 Wabi-sabi ==================== */
.style-wabisabi-demo {
  position: relative; overflow: hidden; border-radius: 10px;
  min-height: 196px; padding: 24px 30px;
  background-color: #f5f2ea;
  background-image: radial-gradient(rgba(122,112,90,.06) 1px, transparent 1.2px);
  background-size: 5px 5px;
  color: #33322e;
  font-family: "Songti SC", "Noto Serif SC", "STSong", serif;
}
.style-wabisabi-title { font-size: 24px; font-weight: 500; letter-spacing: 8px; color: #2e2d29; }
.style-wabisabi-line { width: 36px; height: 1px; background: #a8a294; }
.style-wabisabi-v { writing-mode: vertical-rl; letter-spacing: 8px; }
.style-wabisabi-seal {
  display: inline-flex; align-items: center; justify-content: center;
  width: 28px; height: 28px; border-radius: 3px;
  background: #b8452f; color: #f5f2ea; font-size: 14px;
  font-family: "Songti SC", "Noto Serif SC", serif;
  box-shadow: 0 1px 2px rgba(120,40,20,.3);
}
/* 配方拆解 */
.style-wabisabi-anat { display: inline-flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.style-wabisabi-sw {
  display: inline-flex; align-items: center; justify-content: center;
  width: 76px; height: 44px; border-radius: 3px; border: 1px solid var(--border-light);
  font-size: 12px; color: var(--text-2); overflow: hidden;
}
.style-wabisabi-anat-plus { font-size: 13px; color: var(--text-3); }

