/* domains/design/style-bauhaus.css */
/* ---- Bauhaus 包豪斯 ---- */
.bauhaus-demo {
  max-width: 640px;
  margin: 0 auto;
}
.bauhaus-page {
  background: #f4efe6;
  border: 2px solid #1d2129;
  border-radius: 10px;
  overflow: hidden;
}
.bauhaus-top {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 10px 18px;
  border-bottom: 2px solid #1d2129;
}
.bauhaus-top b {
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 1px;
}
.bauhaus-top span {
  font-size: 14px;
  color: var(--text-2);
}
.bauhaus-main {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 20px 22px;
}
.bauhaus-geo {
  position: relative;
  flex: none;
  width: 168px;
  height: 148px;
}
.bauhaus-shape {
  position: absolute;
  display: block;
}
.bauhaus-shape.circle {
  left: 0;
  top: 8px;
  width: 92px;
  height: 92px;
  border-radius: 50%;
  background: #e64433;
}
.bauhaus-shape.square {
  right: 0;
  top: 0;
  width: 52px;
  height: 52px;
  background: #2b5fc7;
}
.bauhaus-shape.triangle {
  right: 8px;
  bottom: 0;
  width: 0;
  height: 0;
  border-left: 30px solid transparent;
  border-right: 30px solid transparent;
  border-bottom: 52px solid #f0b41e;
}
.bauhaus-shape.bar {
  left: 10px;
  bottom: 18px;
  width: 76px;
  height: 12px;
  background: #1d2129;
}
.bauhaus-copy {
  flex: 1;
  min-width: 0;
}
.bauhaus-copy small {
  font-size: 12px;
  letter-spacing: 2px;
  color: var(--text-3);
}
.bauhaus-copy h2 {
  margin: 6px 0 4px;
  font-size: 24px;
  font-weight: 800;
}
.bauhaus-copy p {
  margin: 0 0 12px;
  font-size: 16px;
  color: var(--text-2);
}
.bauhaus-copy b {
  font-size: 14px;
  font-weight: 700;
  border-bottom: 2px solid #1d2129;
  padding-bottom: 2px;
}
.bauhaus-copy i {
  font-style: normal;
}
.bauhaus-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  padding: 12px 22px;
  border-top: 2px solid #1d2129;
}
.bauhaus-legend span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 14px;
}
.bauhaus-dot {
  display: inline-block;
  width: 14px;
  height: 14px;
}
.bauhaus-dot.circle {
  border-radius: 50%;
  background: #e64433;
}
.bauhaus-dot.triangle {
