.diff-stat { font-size:12px; }
.diff-stat .a { color: var(--green); }
.diff-stat .d { color: var(--red); }
.diff-line { display: block; padding: 1px 10px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.diff-add { background: var(--green-light); color: var(--green); }
.diff-del { background: var(--red-light); color: var(--red); }
.diff-ctx { color: var(--text-3); }
.diff-hunk { background: #ddf4ff; color: #57606a; }
.diff-anat { width: 100%; background: var(--bg); border: 1px solid var(--border); border-radius: 8px; overflow: hidden; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size:12px; line-height: 1.7; }
.diff-anat .diff-line { padding: 2px 12px; }

