/* ===== pack: technology ===== */
/* domains/technology/foundations.css */
/* ---- 技术类目录卡片：从详情图中提取各自的核心关系 ---- */

.tech-card-visual {
  width: min(420px, 100%);
  min-width: 0;
  color: var(--text);
  font-size: 11px;
}

.tech-card-visual *,
.tech-card-visual *::before,
.tech-card-visual *::after {
  box-sizing: border-box;
}

.tech-card-visual code,
.tech-card-visual button {
  font: inherit;
}

.tech-card-visual button {
  border: 0;
  cursor: default;
}

.tc-foot {
  color: var(--text-3);
  font-size: 10px;
  line-height: 1.35;
  text-align: center;
}

/* Tech stack */
.tc-stack {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(105px, 0.65fr);
  align-items: center;
  gap: 10px;
}
.tc-stack-files {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}
.tc-stack-files span {
  display: grid;
  gap: 3px;
  min-width: 0;
  padding: 7px 8px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg);
}
.tc-stack-files small,
.tc-stack-output small {
  color: var(--text-3);
  font-size: 9px;
}
.tc-stack-files b {
  overflow: hidden;
  color: var(--text-2);
  font-size: 10px;
  text-overflow: ellipsis;
}
.tc-stack-output {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 7px;
}
.tc-stack-output > i {
  color: var(--brand);
  font-style: normal;
}
.tc-stack-output span {
  display: grid;
  gap: 4px;
  padding: 10px 8px;
  border-radius: 8px;
  color: var(--brand);
  background: var(--brand-light);
}
.tc-stack-output b {
  font-size: 10px;
  line-height: 1.4;
}

/* JavaScript */
.tc-javascript {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(100px, 0.55fr);
  align-items: center;
  gap: 11px;
}
.tc-js-code {
  overflow: hidden;
  display: grid;
  padding: 6px 0;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
}
.tc-js-code code {
  overflow: hidden;
  padding: 4px 8px;
  color: var(--text-3);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tc-js-code code.active {
  color: var(--brand);
  background: var(--brand-light);
}
.tc-js-result {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 5px;
}
.tc-js-result button {
  padding: 6px 8px;
  border-radius: 6px;
  color: white;
  background: var(--brand);
}
.tc-js-result i {
  color: var(--brand);
  font-style: normal;
}
.tc-js-result .ok {
  padding: 6px;
  border-radius: 6px;
  color: var(--green);
  background: var(--green-light);
  text-align: center;
}

/* TypeScript */
.tc-typescript {
  display: grid;
  grid-template-columns: minmax(90px, 0.55fr) minmax(0, 1.45fr);
  align-items: center;
  gap: 9px 12px;
}
.tc-ts-code {
  display: grid;
  gap: 5px;
  padding: 9px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
}
.tc-ts-code code {
  font-size: 13px;
}
.tc-ts-code code u {
  color: var(--red);
  text-decoration-style: wavy;
}
.tc-ts-code small {
  color: var(--text-3);
  font-size: 9px;
}
.tc-ts-compare {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 6px;
}
.tc-ts-compare span {
  display: grid;
  gap: 5px;
  padding: 8px;
  border-radius: 7px;
}
.tc-ts-compare small {
  font-size: 8px;
}
.tc-ts-compare b {
  font-size: 9px;
  line-height: 1.35;
}
.tc-ts-compare .js {
  color: var(--text-2);
  background: var(--bg-soft);
}
.tc-ts-compare .ts {
  color: var(--red);
  background: var(--red-light);
}
.tc-typescript .tc-foot {
  grid-column: 1 / -1;
}

/* Python */
.tc-python {
  display: grid;
  grid-template-columns: 1fr 1.2fr auto 0.8fr;
  align-items: center;
  gap: 6px;
}
.tc-python-files {
  display: grid;
  gap: 3px;
}
.tc-python-files span {
  overflow: hidden;
  padding: 4px 6px;
  border: 1px solid var(--border);
  border-radius: 5px;
  background: var(--bg);
  color: var(--text-2);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tc-python-script,
.tc-python-output {
  display: grid;
  gap: 5px;
  padding: 9px 7px;
  border-radius: 7px;
}
.tc-python-script {
  border: 1px solid color-mix(in srgb, var(--brand) 35%, var(--border));
  background: var(--brand-light);
}
.tc-python-script code {
  color: var(--brand);
  font-weight: 700;
}
.tc-python-script small,
.tc-python-output small {
  color: var(--text-3);
  font-size: 8px;
  line-height: 1.35;
}
.tc-python > i {
  color: var(--brand);
  font-style: normal;
}
.tc-python-output {
  color: var(--green);
  background: var(--green-light);
}

/* React */
.tc-react {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(105px, 0.65fr);
  align-items: center;
  gap: 9px 12px;
}
.tc-react-code {
  overflow: hidden;
  display: grid;
  gap: 2px;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
}
