  overflow: hidden;
  padding: 4px 5px;
  color: var(--brand);
  background: var(--brand-light);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tc-react-preview {
  display: grid;
  gap: 6px;
  padding: 9px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
}
.tc-react-preview small {
  color: var(--text-2);
  font-size: 9px;
}
.tc-react-preview button {
  padding: 5px 7px;
  border-radius: 5px;
  color: white;
  background: var(--brand);
}
.tc-react-preview span {
  color: var(--green);
  font-size: 9px;
}
.tc-react .tc-foot {
  grid-column: 1 / -1;
}

/* Vue */
.tc-vue {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 7px 9px;
}
.tc-vue-ref,
.tc-vue-preview {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 9px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
}
.tc-vue-ref small,
.tc-vue-preview small {
  color: var(--text-3);
  font-size: 9px;
}
.tc-vue-ref code {
  overflow: hidden;
  color: var(--green);
  font-size: 9px;
  text-overflow: ellipsis;
