}
.tc-vue-bind {
  display: grid;
  justify-items: center;
  gap: 3px;
  color: var(--text-3);
}
.tc-vue-bind i {
  font-size: 8px;
  font-style: normal;
}
.tc-vue-bind code {
  color: var(--green);
  font-size: 9px;
}
.tc-vue-preview button {
  padding: 5px 7px;
  border-radius: 5px;
  color: white;
  background: #15803d;
}
.tc-vue .tc-foot {
  grid-column: 1 / -1;
}

/* Next.js */
.tc-next {
