.testing-delivery-preview button { pointer-events: none; }
.tdv-sheet, .tdv-login, .tdv-code, .tdv-browser, .tdv-probes, .tdv-receipt, .tdv-terminal, .tdv-pr, .tdv-jobs, .tdv-stage-site, .tdv-tree, .tdv-request, .tdv-table, .tdv-runs, .tdv-editor, .tdv-monitor, .tdv-rollback, .tdv-flag, .tdv-release-split, .tdv-environment-switch {
