.tdv-request :is(dt, dd) { margin: 0; padding: 6px 0; border-bottom: 1px solid #eceef0; font-family: ui-monospace, monospace; }
.tdv-request dt { color: var(--text-2); }
.tdv-request dd.is-pass { color: var(--td-pass); font-weight: 750; }
.tdv-table header, .tdv-table p { display: grid; grid-template-columns: .8fr 1.5fr .7fr; gap: 8px; }
.tdv-table p { padding: 12px; background: var(--td-pass-soft); }
.tdv-table p em { color: var(--text-2); font-style: normal; }
.tdv-table small { display: block; padding: 9px 12px; color: var(--text-2); text-align: center; }
.tdv-runs p { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; padding: 5px 12px; }
.tdv-runs p span { padding: 5px 7px; color: var(--td-pass); background: var(--td-pass-soft); }
.tdv-runs p span.is-fail { color: var(--td-alert); background: var(--td-alert-soft); }
.tdv-runs small { display: block; padding: 8px 12px 12px; color: var(--text-2); }
.tdv-editor { display: grid; gap: 3px; }
.tdv-editor code { display: grid; grid-template-columns: 26px minmax(0, 1fr); padding: 4px 6px; }
.tdv-editor code i { color: var(--text-2); font-style: normal; }
.tdv-editor code.is-error { color: #fff; background: #6a3439; }
.tdv-editor b { margin-top: 7px; padding: 7px; color: #ffd5d5; background: #4b2f32; }
.tdv-monitor { padding: 13px 15px; }
.tdv-monitor header span { font-weight: 700; }
.tdv-monitor header b { color: var(--td-alert); font-size: 19px; }
.tdv-monitor > div { display: flex; align-items: flex-end; gap: 8px; height: 72px; border-bottom: 1px solid #d9dde1; }
.tdv-monitor > div i { flex: 1; height: 20%; background: #717b86; }
.tdv-monitor > div i.is-high { height: 80%; background: var(--td-alert); }
.tdv-monitor > em { display: block; padding-top: 7px; color: var(--td-alert); font-style: normal; }
.tdv-rollback { padding: 10px 14px; }
.tdv-rollback p { display: flex; justify-content: space-between; padding: 8px; border-bottom: 1px solid #eceef0; }
.tdv-rollback p.is-live { color: var(--td-pass); background: var(--td-pass-soft); }
.tdv-rollback p em { font-style: normal; }
.tdv-rollback footer { padding: 10px 8px 3px; color: var(--text-2); }
.tdv-rollback footer b { color: var(--td-pass); }
.tdv-flag { padding: 12px 14px; }
.tdv-flag header b { padding: 3px 7px; border-radius: 99px; color: var(--on-status); background: var(--td-pass); }
.tdv-flag section { display: grid; grid-template-columns: repeat(2, 1fr); gap: 9px; }
.tdv-flag p { display: grid; gap: 6px; padding: 11px; background: var(--bg-hover); }
.tdv-flag p:first-child { color: #fff; background: #303840; }
.tdv-flag small { color: inherit; opacity: .72; }
.tdv-release-split { padding: 12px 14px; }
.tdv-release-split header, .tdv-environment-switch > header { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 9px; }
.tdv-release-split header span, .tdv-environment-switch > header span { color: var(--text-2); }
.tdv-release-split p { display: grid; grid-template-columns: 90px minmax(0, 1fr) 36px; align-items: center; gap: 8px; min-height: 34px; }
.tdv-release-split p i { display: block; width: var(--share); min-width: 3px; height: 8px; background: #5f6872; }
.tdv-release-split p.is-canary i { background: var(--td-alert); }
.tdv-release-split p em { font-style: normal; text-align: right; }
.tdv-release-split footer { margin-top: 8px; padding-top: 8px; color: var(--text-2); border-top: 1px solid #eceef0; }
.tdv-release-split footer b { color: var(--td-alert); }
.tdv-environment-switch { padding: 12px 14px; }
.tdv-environment-switch > header b { color: var(--td-pass); }
.tdv-environment-switch section { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 9px; }
.tdv-environment-switch section > i { color: var(--text-2); font-style: normal; }
.tdv-environment-switch section p { display: grid; gap: 4px; padding: 10px; color: #fff; background: var(--td-blue, #365f86); }
.tdv-environment-switch section p.is-live { background: var(--td-pass); }
.tdv-environment-switch section p small { opacity: .72; }
.tdv-environment-switch section p em { font-style: normal; opacity: .82; }
.tdv-environment-switch footer { padding-top: 9px; color: var(--text-2); text-align: center; }

@media (max-width: 760px) {
  .td-controls { gap: 16px; overflow-x: auto; }
  .td-controls button { flex: 0 0 auto; }
  .td-acceptance-body, .td-login-scene, .td-receipt, .td-pr-body, .td-double-layout, .td-lint-layout, .td-flag-grid { grid-template-columns: 1fr; }
  .td-criteria-list, .td-login-scene > aside, .td-receipt aside, .td-pr-body aside { border-right: 0; border-bottom: 1px solid var(--td-line); }
  .td-login-scene form { padding: 28px; }
  .td-checkout { grid-template-columns: 1fr; }
  .td-checkout > aside { border-top: 1px solid var(--td-line); border-left: 0; }
  .td-probe-log { grid-template-columns: 1fr; gap: 13px; }
  .td-build-layout { grid-template-columns: 125px minmax(0, 1fr); }
  .td-build-layout main { grid-template-columns: 1fr; }
  .td-artifact-tree { border-top: 1px solid #3b4148; border-left: 0; }
  .td-tree-branches { width: 100%; gap: 24px; }
  .td-flag-grid > main { grid-template-columns: 1fr; }
  .td-version-lanes { grid-template-columns: 1fr; }
}
@media (max-width: 520px) {
  .td-controls { margin-bottom: 16px; gap: 14px; }
  .td-controls button { min-height: 42px; font-size: 14px; }
  .td-controls button span { width: 22px; height: 22px; }
  .td-proof { padding: 14px 16px 16px; font-size: 15px; }
  .td-browser-bar { grid-template-columns: 8px 8px 8px minmax(0, 1fr); padding-inline: 11px; }
  .td-browser-bar b { grid-column: 1 / -1; justify-self: start; }
  .td-acceptance-body, .td-integration-grid { grid-template-columns: 1fr; }
  .td-criteria-list { padding: 22px; border-right: 0; border-bottom: 1px solid var(--td-line); }
  .td-itinerary { padding: 22px; }
  .td-login-scene > aside, .td-login-scene form { padding: 22px; }
  .td-editor-layout, .td-build-layout { grid-template-columns: 1fr; }
  .td-editor-layout nav, .td-build-layout nav { display: flex; flex-wrap: wrap; border-right: 0; border-bottom: 1px solid var(--td-line); }
  .td-terminal-panel { grid-template-columns: 1fr; }
  .td-terminal-panel small { grid-column: auto; }
  .td-booking-form { min-height: auto; border-right: 0; border-bottom: 1px solid var(--td-line); }
  .td-network-pane { min-height: 220px; }
  .td-table-head, .td-table-row { grid-template-columns: 1fr 1fr; }
  .td-table-head span:last-child, .td-table-row span:last-child { display: none; }
  .td-journey { padding: 18px; }
  .td-trip-product, .td-checkout > div, .td-checkout > aside { padding: 22px; }
  .td-receipt main, .td-receipt aside, .td-pr-body main, .td-pr-body aside { padding: 22px; }
  .td-repo-page > header { grid-template-columns: 1fr; gap: 8px; }
  .td-job-list { padding-inline: 16px; }
  .td-job-list > div { grid-template-columns: 28px minmax(0, 1fr); }
  .td-job-list button { grid-column: 2; justify-self: start; margin-bottom: 12px; }
  .td-cd-key { grid-template-columns: 1fr; gap: 7px; }
  .td-staging main { padding-inline: 18px; }
  .td-staging main > header span { display: none; }
  .td-tree { padding-inline: 14px; }
  .td-tree-branches { grid-template-columns: 1fr; gap: 20px; }
  .td-tree-split { display: none; }
  .td-tree-branches section::before { height: 22px; }
  .td-repeat-row { grid-template-columns: 1fr; }
  .td-db-table { margin-inline: 14px; overflow-x: auto; }
  .td-db-head, .td-db-row { min-width: 580px; }
  .td-fixture ol { grid-template-columns: 1fr; gap: 10px; padding-inline: 18px; }
  .td-run-table { padding-inline: 14px; overflow-x: auto; }
  .td-run-table > div { min-width: 460px; }
  .td-trace-clue { grid-template-columns: 1fr; margin-inline: 14px; }
  .td-metric-chart { margin-inline: 16px; }
  .td-alert-row { grid-template-columns: 24px minmax(0, 1fr); margin-inline: 16px; }
  .td-alert-row code { grid-column: 2; }
  .td-release-history { padding-inline: 14px; }
  .td-release-history > div { grid-template-columns: 90px minmax(0, 1fr); }
  .td-release-history > div b { grid-column: 2; padding-bottom: 10px; }
  .td-health-strip { grid-template-columns: 64px minmax(0, 1fr) 48px; padding-inline: 14px; }
  .td-flag-grid > main, .td-flag-grid > aside { padding: 18px; }
  .td-canary-routing, .td-environment-routing { padding: 16px; }
  .td-route-shares { display: none; }
  .td-environment-pools { grid-template-columns: 1fr; }
  .td-environment-pools > section { opacity: 1; }
}

/* 契约测试 */
.td-contract-board { padding: 22px; }
.td-contract-step { max-width: 780px; margin: 0 auto; }
.td-contract-step > .td-badge { display: block; margin-bottom: 14px; color: var(--td-muted); font-size: 14px; font-weight: 750; }
.td-contract-step > .td-badge.is-warn, .td-contract-step > .td-badge.is-fail { color: var(--td-alert); }
.td-contract-pair { display: grid; grid-template-columns: minmax(0, 1fr) 30px minmax(0, 1fr); align-items: stretch; gap: 10px; }
.td-contract-pair > section { min-width: 0; overflow: hidden; border: 1px solid var(--td-line); border-radius: 8px; background: var(--td-faint); }
.td-contract-pair > section.is-broken { border-color: #e2a8ac; background: var(--td-alert-soft); }
.td-contract-pair > section small { display: block; padding: 10px 13px; border-bottom: 1px solid var(--td-line); color: var(--td-muted); background: var(--bg); font-size: 14px; font-weight: 750; }
.td-contract-pair pre { min-height: 150px; margin: 0; padding: 16px; overflow: auto; color: var(--td-ink); font: 14px/1.65 ui-monospace, SFMono-Regular, Menlo, monospace; white-space: pre-wrap; }
.td-contract-pair > i { display: grid; place-items: center; color: var(--td-muted); font-size: 21px; font-style: normal; }
.td-contract-checks { overflow: hidden; border: 1px solid var(--td-line); border-radius: 9px; background: var(--bg); }
.td-contract-checks > header { display: flex; justify-content: space-between; gap: 16px; padding: 13px 16px; border-bottom: 1px solid var(--td-line); background: var(--td-faint); font-size: 14px; }
.td-contract-checks > header b { color: var(--td-alert); }
.td-contract-result { display: grid; gap: 8px; margin: 18px; padding: 16px; border-radius: 7px; font-size: 14px; line-height: 1.55; }
.td-contract-result.is-failed { color: var(--td-alert); background: var(--td-alert-soft); }
.td-contract-result code { overflow-wrap: anywhere; color: inherit; font: 14px/1.55 ui-monospace, SFMono-Regular, Menlo, monospace; }
.td-contract-checks > button { display: block; min-width: 150px; min-height: 42px; margin: 0 18px 18px auto; border: 0; border-radius: 6px; color: var(--text-2); background: var(--bg-hover); font-size: 14px; font-weight: 750; }

@media (max-width: 520px) {
  .td-contract-board { padding: 16px; }
  .td-contract-pair { grid-template-columns: 1fr; }
  .td-contract-pair > i { min-height: 26px; font-size: 0; }
  .td-contract-pair > i::before { content: "↓"; font-size: 21px; }
}
